// Giải thích tham khảo cho từng câu (không thuộc tài liệu gốc).
window.QUIZ_EXPLAIN = {"w1-001":"Với môn Tin học, giai đoạn giáo dục cơ bản được tính từ lớp 3 (khi bắt đầu học môn Tin học và Công nghệ) đến hết lớp 9; lớp 10–12 thuộc giai đoạn giáo dục định hướng nghề nghiệp.",
"w1-002":"Ở THPT, môn Tin học phân hóa theo hai định hướng: Tin học ứng dụng (ICT) và Khoa học máy tính (CS). Các cặp còn lại là tên lĩnh vực/ngành học, không phải định hướng của chương trình.",
"w1-003":"Chương trình nhấn mạnh công nghệ số là nền tảng kết nối các khoa học và công nghệ hiện đại (cơ sở cho giáo dục STEM/STEAM). Các phương án khác mô tả mạch kiến thức hoặc sản phẩm, không phải vai trò của công nghệ số.",
"w1-004":"Ở tiểu học, Tin học và Công nghệ là môn bắt buộc từ lớp 3 đến lớp 5; lớp 1 và lớp 2 chưa học môn này.",
"w1-005":"NLc là “Giải quyết vấn đề với sự hỗ trợ của CNTT-TT”. Nhớ thứ tự: NLa sử dụng, quản lí phương tiện; NLb ứng xử trong môi trường số; NLc giải quyết vấn đề; NLd học và tự học; NLe hợp tác.",
"w1-006":"Mạch Khoa học máy tính (CS) gắn với tư duy máy tính (tư duy tính toán). DL hướng tới học vấn số, ICT hướng tới ứng dụng công nghệ; STEAM không phải mạch kiến thức của môn.",
"w1-007":"Năm phẩm chất chủ yếu là: yêu nước, nhân ái, chăm chỉ, trung thực, trách nhiệm. “Tự tin” không nằm trong danh sách này.",
"w1-008":"NLe là “Hợp tác trong môi trường số”. Giải quyết vấn đề là NLc, ứng xử là NLb, sử dụng và quản lí phương tiện là NLa.",
"w1-009":"Kế thừa và phát triển là một quan điểm xây dựng chương trình môn Tin học: giữ lại cái phù hợp của chương trình trước, cập nhật cái mới. Các cụm còn lại không được nêu là quan điểm xây dựng chương trình.",
"w1-010":"Ở THCS (lớp 6–9), Tin học là môn học bắt buộc; chỉ ở THPT môn này mới là môn lựa chọn.",
"w1-011":"Ba mạch kiến thức của môn Tin học là: Học vấn số hoá phổ thông (DL), Công nghệ thông tin và truyền thông (ICT), Khoa học máy tính (CS). Khoa học dữ liệu, AI hay DCT không phải tên mạch.",
"w1-012":"Năm phẩm chất chủ yếu là yêu nước, nhân ái, chăm chỉ, trung thực, trách nhiệm. Tự chủ, sáng tạo, hợp tác thuộc năng lực chung chứ không phải phẩm chất.",
"w1-013":"Chương trình môn Tin học nêu 4 quan điểm xây dựng chương trình (trong đó có kế thừa và phát triển, tính mở…).",
"w1-014":"“Ứng xử phù hợp trong môi trường số” là NLb. NLa là sử dụng và quản lí phương tiện, NLc là giải quyết vấn đề, NLd là học và tự học.",
"w1-015":"Ở THCS, Tin học là môn học bắt buộc với mọi học sinh, không phải môn tự chọn, môn tích hợp với Công nghệ hay môn chuyên sâu.",
"w1-016":"“Giao tiếp và hợp tác” là năng lực chung của mọi môn, không phải thành phần của năng lực tin học. Năm thành phần năng lực tin học là NLa–NLe (trong đó NLe là “Hợp tác trong môi trường số”).",
"w1-017":"Chương trình được xây dựng từ ba mạch DL, ICT, CS. STEM/STEAM là định hướng giáo dục, AI chỉ là một chủ đề nội dung.",
"w1-018":"Hai định hướng ở THPT là Tin học ứng dụng và Khoa học máy tính, tương ứng với mạch ICT và mạch CS.",
"w1-019":"Ở THPT, Tin học là môn lựa chọn, có vị trí bình đẳng với các môn lựa chọn khác; không bắt buộc, không tích hợp và không dành riêng cho nhóm học sinh nào.",
"w1-020":"Ở tiểu học, Tin học được ghép với Công nghệ thành môn “Tin học và Công nghệ”, gồm hai phân môn độc lập.",
"w1-021":"Ở THPT, Tin học là môn lựa chọn, bình đẳng với các môn lựa chọn khác. “Ghép hai phân môn” là đặc điểm ở tiểu học; phân hóa theo định hướng diễn ra bên trong môn chứ không phải lí do lựa chọn môn.",
"w1-022":"Ba mạch cốt lõi là DL, ICT, CS. Hệ thống thông tin, an ninh mạng, khoa học dữ liệu chỉ là các chủ đề, không phải mạch kiến thức.",
"w1-023":"Ba mạch cốt lõi gồm CS, ICT và Học vấn số hoá phổ thông (DL). Các phương án khác thay DL bằng những tên không có trong chương trình.",
"w1-024":"Ở tiểu học, Tin học và Công nghệ là môn học bắt buộc, gồm hai phân môn Tin học và Công nghệ (ghép cơ học, mỗi phân môn có mục tiêu riêng).",
"w1-025":"NLe là “Hợp tác trong môi trường số”. Sử dụng phương tiện là NLa, ứng xử là NLb, học và tự học là NLd.",
"w1-026":"Ở THPT, Tin học là môn học lựa chọn (thuộc nhóm môn lựa chọn), không phải môn bắt buộc hay tự chọn.",
"w1-027":"Ba mạch kiến thức viết tắt là DL (Digital Literacy), ICT và CS (Computer Science).",
"w1-028":"Theo kế hoạch giáo dục THPT, học sinh chọn môn trong nhóm môn lựa chọn (có Tin học, Công nghệ, Nghệ thuật…) theo quy định của chương trình tổng thể.",
"w1-029":"Tính mở về nội dung đòi hỏi cập nhật định kì ngắn hạn để bảo đảm tính hiện đại, thời sự, vì công nghệ số thay đổi rất nhanh. Các phương án khác nói về sự phù hợp với học sinh hoặc điều kiện trường, không phải lí do phải cập nhật thường xuyên.",
"w1-030":"Ba mạch nền tảng là DL, ICT, CS. Kĩ thuật máy tính, khoa học dữ liệu, AI hay hệ thống thông tin không phải mạch của chương trình.",
"w1-031":"Tìm kiếm và dùng thông tin hiệu quả để giải quyết nhiệm vụ là biểu hiện của NLc (giải quyết vấn đề với sự hỗ trợ của CNTT-TT).",
"w1-032":"Hiểu tầm quan trọng của thông tin và xử lí thông tin là một biểu hiện của NLc (giải quyết vấn đề với sự hỗ trợ của CNTT-TT), không phải của năng lực ứng xử, tự học hay sử dụng thiết bị.",
"w1-033":"Phát triển thuật toán và cấu trúc dữ liệu thuộc định hướng Khoa học máy tính. Định hướng Tin học ứng dụng chú trọng sử dụng thành thạo công cụ, phần mềm để tạo sản phẩm số.",
"w1-034":"Mạch DL hướng tới sử dụng thiết bị số và mạng một cách có đạo đức, văn hoá và tuân thủ pháp luật để hoà nhập xã hội số. Thiết kế hệ thống, cấu trúc dữ liệu, giải quyết vấn đề sáng tạo là trọng tâm của mạch CS.",
"w1-035":"THPT là giai đoạn giáo dục định hướng nghề nghiệp, nên môn Tin học chú trọng định hướng nghề và giới thiệu ngành nghề trong lĩnh vực tin học. Các phương án khác chỉ là “nâng mức độ”, không phải điểm khác biệt căn bản.",
"w1-036":"Nội dung môn học được xác định dựa trên nghiên cứu, chọn lọc yêu cầu cần đạt từ các tổ chức giáo dục quốc tế uy tín và tham vấn chuyên gia. Không dựa vào điểm thi học sinh giỏi, khảo sát doanh nghiệp, cũng không sao chép nguyên chương trình đại học.",
"w1-037":"Ở THCS, Tin học chuyển từ môn tự chọn (chương trình cũ) thành môn bắt buộc. Môn này không bị cắt giảm, không gộp với Toán và không chuyển thành ngoại khoá.",
"w1-038":"Phát triển theo đường thẳng là kiến thức nối tiếp nhau theo trình tự logic; phát triển đồng tâm là chủ đề cốt lõi được lặp lại và nâng cao dần ở các lớp sau. Phương án mô tả ngược hai khái niệm là sai.",
"w1-039":"Chủ động tìm tài liệu, dùng công cụ số để tự luyện tập ngoài giờ là biểu hiện của NLd: ứng dụng CNTT-TT trong học và tự học.",
"w1-040":"Môn Tin học không chỉ dạy dùng máy tính mà còn hình thành tư duy máy tính (tư duy tính toán) để giải quyết vấn đề. Môn này không nhằm đào tạo chuyên sâu nghề CNTT, và việc hỗ trợ đổi mới các môn khác không phải lí do cốt lõi.",
"w1-041":"DL giúp học sinh dùng thiết bị số có đạo đức để hoà nhập xã hội số; CS giúp hiểu tư duy máy tính, làm cơ sở thiết kế hệ thống. Các phương án còn lại đảo lộn hoặc thu hẹp vai trò hai mạch.",
"w1-042":"Theo chương trình, Khoa học máy tính là nền tảng kết nối các ngành khoa học, bản thân kiến thức đã chứa các yếu tố của mô hình STEAM. Các phương án khác chỉ coi CS là công cụ hoặc phương tiện hỗ trợ.",
"w1-043":"Sản phẩm số có giá trị khi có nội dung thực tế, công cụ xử lí (như Toán) và khả năng diễn đạt (Ngôn ngữ, Mĩ thuật). Đó là đóng góp của các môn khác, chứ không phải giảm lí thuyết hay đơn giản hoá thuật toán.",
"w1-044":"Coi dạy Tin học chỉ là dạy thao tác máy tính là thu hẹp bản chất môn học, bỏ qua tư duy thuật toán và năng lực giải quyết vấn đề, vốn là cốt lõi của chương trình.",
"w1-045":"Sự gắn kết lí thuyết với thực hành thể hiện rõ nhất khi học sinh vận dụng ICT để giải quyết vấn đề thực tiễn. Các phương án khác mới dừng ở mức sử dụng hoặc hình thành kĩ năng.",
"w1-046":"Tin học ứng dụng chú trọng vận dụng ICT vào học tập và đời sống; Khoa học máy tính chú trọng tư duy tính toán và giải quyết vấn đề (thuật toán, lập trình).",
"w1-047":"Tính mở về phương pháp và phương thức cho phép tổ chức dạy học đa dạng: trực tuyến, phòng thực hành ảo… tuỳ điều kiện. Cập nhật nội dung là tính mở về nội dung, định hướng nghề không phải là tính mở.",
"w1-048":"Ở tiểu học, Tin học và Công nghệ là sự ghép cơ học hai phân môn có mục tiêu và yêu cầu cần đạt độc lập, không tích hợp thành chủ đề chung.",
"w1-049":"DL giúp hoà nhập xã hội số; ICT giúp giải quyết vấn đề thực tế bằng máy tính; CS giúp hiểu tư duy máy tính và thiết kế hệ thống. Các phương án khác gán sai trọng tâm cho CS (chỉ là dùng sản phẩm số có sẵn).",
"w1-050":"CS phát triển tư duy giải quyết vấn đề trên nền tảng công nghệ số; ICT rèn khả năng ứng dụng CNTT để tạo sản phẩm phục vụ thực tiễn. Phương án nói mục tiêu hai phân môn ở tiểu học “thống nhất” là sai, vì chúng độc lập.",
"w1-051":"Theo chương trình, yêu cầu cần đạt (những gì học sinh làm được sau chủ đề) là căn cứ để xây dựng công cụ đánh giá; vì vậy cách của giáo viên B đúng. Tuy vậy không phải mọi yêu cầu cần đạt đều phải chuyển thành câu hỏi kiểm tra.",
"w1-052":"Qua hoạt động trải nghiệm và sáng tạo sản phẩm, chương trình chú trọng nhiều định hướng giáo dục: STEM, hướng nghiệp, tài chính, bình đẳng giới, dân số và sức khoẻ. Các phương án khác lẫn vào nội dung môn học (thuật toán, lập trình, sản phẩm số).",
"w1-053":"Dùng công nghệ số luôn gắn với xã hội và thế giới số, nên giáo dục Tin học phải “vừa dạy chữ vừa dạy người”. Đó là lí do cốt lõi; các phương án khác chỉ nêu tác dụng bộ phận.",
"w1-054":"Kế thừa nghĩa là giữ ưu điểm về tính chính xác khoa học của chương trình hiện hành, đồng thời tránh những điểm yếu của nó, nên không thể giữ nguyên.",
"w1-055":"Mạch CS giúp học sinh hiểu các nguyên tắc của tư duy máy tính, làm cơ sở thiết kế và phát triển hệ thống máy tính. Khai thác thiết bị và dùng an toàn là DL; vận dụng hệ thống máy tính giải quyết vấn đề là ICT.",
"w1-056":"DL trọng tâm là sử dụng thiết bị, phần mềm số phù hợp; ICT trọng tâm là giải quyết vấn đề thực tiễn dựa trên hệ thống máy tính. Phương án đúng giữ đúng thứ tự DL rồi đến ICT.",
"w1-057":"Ở giai đoạn giáo dục cơ bản (lớp 3–9), Tin học là môn bắt buộc; ở THPT, Tin học là môn lựa chọn.",
"w1-058":"Chương trình dùng Khoa học máy tính để đẩy mạnh giáo dục STEM, đặt người học vào vị thế “nhà phát minh” giải quyết vấn đề, không coi Tin học chỉ là công cụ tính toán hay thao tác phần mềm.",
"w1-059":"Câu hỏi tìm nhận định SAI. Tin học và Công nghệ ở tiểu học là ghép cơ học hai phân môn có mục tiêu và nội dung độc lập, không phải tích hợp để thống nhất mục tiêu.",
"w1-060":"Công nghệ số xử lí thông tin/dữ liệu (vô hình), “nối dài” trí tuệ con người, khác căn bản với công nghệ xử lí vật chất hữu hình. Vì vậy không thể đồng nhất Tin học với môn Công nghệ.",
"w1-061":"Từ tìm kiếm đơn giản ở tiểu học lên tìm từ nhiều nguồn và đánh giá thông tin ở THCS: đó là yêu cầu cần đạt tăng dần từ thực hiện đơn giản đến phân tích, đánh giá, vận dụng.",
"w1-062":"Mục tiêu chủ đạo của DL là giúp học sinh hoà nhập xã hội số, sử dụng công nghệ có văn hoá, đạo đức và đúng pháp luật. Lập trình, thuật toán thuộc CS; sửa chữa phần cứng không phải mục tiêu của mạch nào.",
"w1-063":"Học sinh có kĩ năng dùng công cụ tìm kiếm nhưng chia sẻ thông tin chưa kiểm chứng, tức là còn thiếu năng lực ứng xử trong môi trường số (NLb) và cần được bồi dưỡng thêm.",
"w1-064":"Muốn làm lập trình viên, thiết kế hệ thống thì nên chọn Khoa học máy tính, vì định hướng này phát triển tư duy thuật toán và nguyên tắc thiết kế hệ thống. Định hướng CS không phải môn bắt buộc cho người thi đại học.",
"w1-065":"Thay đổi cốt lõi của GDPT 2018 là chuyển từ trang bị kiến thức sang hình thành và phát triển phẩm chất, năng lực người học.",
"w1-066":"ICT rèn kĩ năng dùng công cụ số; CS phát triển tư duy máy tính và nguyên tắc phát triển hệ thống. Định hướng không chia theo khối ngành xã hội hay tự nhiên, và CS không dạy lắp ráp phần cứng.",
"w1-067":"Tính mở cho phép linh hoạt về phương pháp, môi trường dạy học; chương trình chỉ quy định yêu cầu tối thiểu, không cố định phần mềm. Tính mở không cho phép cắt bỏ yêu cầu cần đạt hay mạch kiến thức cốt lõi.",
"w1-068":"Cùng chỉnh sửa một báo cáo trên Google Docs là hợp tác trong môi trường số (NLe).",
"w1-069":"Dùng bảng tính vẽ biểu đồ trong giờ Toán cho thấy Tin học cung cấp công cụ số giúp các môn khác đổi mới cách dạy và cách học. Hoạt động này không bổ sung kiến thức Toán, cũng không rèn lập trình.",
"w1-070":"Xây dựng chương trình tính tiền điện đòi hỏi phân tích bài toán, thiết kế thuật toán và lập trình, nên phát triển tư duy giải quyết vấn đề (mạch CS).",
"w1-071":"Cho học sinh thiết kế thuật toán và lập trình một bài toán thực (quản lí lịch học bằng Python) vừa rèn kiến thức CS vừa cho trải nghiệm công việc của nghề. Chỉ phát tài liệu hay giới thiệu thì kém hiệu quả.",
"w1-072":"NLd là dùng CNTT-TT để học và tự học: tìm tư liệu rồi phân tích, tổng hợp phục vụ bài học môn khác là đúng trọng tâm. Đánh giá độ tin cậy, bản quyền nghiêng về NLb; tải và sắp xếp tệp nghiêng về NLa.",
"w1-073":"Muốn tạo ấn phẩm truyền thông số thì phù hợp nhất là Tin học ứng dụng, định hướng chú trọng khai thác phần mềm để sáng tạo sản phẩm số.",
"w1-074":"Lớp hướng tới Digital Marketing nên chọn Tin học ứng dụng (tạo ấn phẩm). Đồng thời vẫn học phần cốt lõi chung có kiến thức Khoa học máy tính để rèn tư duy xử lí dữ liệu, không cần thêm lập trình nâng cao.",
"w1-075":"Chương trình hướng tới chọn công cụ số dựa trên đặc điểm đối tượng và dùng kiến thức Tin học tạo sản phẩm giải quyết vấn đề thực tiễn. Làm theo mẫu hay chỉ chú trọng hình thức phần mềm là chưa đạt.",
"w1-076":"Yêu cầu của chương trình là phân tích tình huống thực tế, đề xuất cách xử lí an toàn, có trách nhiệm (ứng xử số), rồi dùng công cụ số tạo sản phẩm. Các phương án khác lệch về thao tác kĩ thuật hoặc phân tích pháp lý.",
"w1-077":"Học sinh lớp 6 cần tự đi qua quy trình: xác định thông tin cần thu thập, chọn dữ liệu phù hợp, phân tích và rút ra kết luận. Như vậy mới giải quyết được vấn đề, thay vì chỉ thao tác công cụ hay trình bày kết quả.",
"w1-078":"Ở THPT, định hướng nghề nghiệp được thực hiện qua việc giải quyết nhiệm vụ gắn với nghề bằng kiến thức về hệ thống, thuật toán, lập trình, không chỉ dùng phần mềm hay tìm hiểu nghề.",
"w1-079":"Để học sinh xử lí được nhiệm vụ mới, cần cho các em phân tích yêu cầu, chọn cách làm, tạo sản phẩm và điều chỉnh khi chưa đạt. Phương án đúng có bước tự điều chỉnh, tức là quá trình giải quyết vấn đề thực sự.",
"w1-080":"Hoạt động gồm xử lí số liệu bằng bảng tính (lưu trữ, xử lí thông tin), lập trình Scratch (giải quyết vấn đề) và chia sẻ trực tuyến để góp ý (hợp tác). Đó là các năng lực cốt lõi ở THCS.",
"w1-081":"Hoạt động trải nghiệm cần để học sinh tự tìm hiểu vấn đề, đề xuất giải pháp, vận dụng kiến thức liên môn và sáng tạo sản phẩm số. Làm theo mẫu hay theo hướng dẫn từng bước không phát huy sáng tạo.",
"w1-082":"Theo định hướng chương trình, mạch Khoa học máy tính là nền tảng cho STEAM: học sinh tự phát hiện vấn đề và sáng tạo sản phẩm có ứng dụng ICT. Chỉ dùng công cụ hay rèn thao tác phần mềm là chưa đủ.",
"w1-083":"Tính mở cho phép linh hoạt phương thức: thiết kế dự án và dùng phòng học ảo để hoàn thiện sản phẩm ngoài giờ. Cắt giảm yêu cầu cần đạt hay bỏ mặc học sinh tự học đều không đúng.",
"w1-084":"Yêu cầu có hai vế: giải quyết vấn đề thực tiễn bằng kiến thức Tin học, và tìm hiểu yêu cầu của nghề. Chỉ phương án đúng nêu đủ cả hai; các phương án khác chỉ “nhận biết” hoặc “mở rộng hiểu biết” chung chung.",
"w1-085":"Câu hỏi tìm hoạt động KHÔNG phù hợp. Cho cả lớp làm y hệt giáo viên thì học sinh không tự phân rã, thử nghiệm, sửa lỗi, nên không phát triển tư duy máy tính.",
"w1-086":"Học sinh tiểu học phù hợp với lập trình trực quan: kéo thả khối lệnh để điều khiển nhân vật. Ghi nhớ cú pháp văn bản, chép mã hay tháo lắp phần cứng đều không phù hợp lứa tuổi và yêu cầu cần đạt.",
"w1-087":"Chủ đề tích hợp đúng phải dùng kiến thức của cả hai phân môn cho cùng một sản phẩm: vẽ mẫu bằng phần mềm (Tin học) rồi làm thủ công (Công nghệ). Gộp bài không liên quan hay để môn này thay thế môn kia là sai.",
"w1-088":"Chia bài toán lớn thành các nhiệm vụ nhỏ (phân rã) để xây dựng thuật toán là cách phát triển năng lực giải quyết vấn đề trong mạch CS.",
"w1-089":"Bồi dưỡng giáo viên phải dựa trên năng lực và yêu cầu cần đạt riêng của từng môn, phân môn, không chỉ dừng ở kĩ năng văn phòng hay vận hành phòng máy.",
"w1-090":"Không cấm AI mà dùng AI làm trợ lý có kiểm soát: học sinh phải giải thích và bảo vệ logic mã của mình. Cách này vừa đảm bảo trung thực vừa phát triển tư duy thực chất.",
"w1-091":"Năng lực tin học gồm 5 thành phần: NLa, NLb, NLc, NLd, NLe.",
"w1-092":"Học sinh muốn theo Công nghệ phần mềm, Trí tuệ nhân tạo nên chọn định hướng Khoa học máy tính, vì định hướng này học sâu về hệ thống, thuật toán và lập trình. DL là mạch kiến thức, không phải định hướng ở THPT.",
"w1-093":"Ở THCS, Tin học là môn học bắt buộc với mọi học sinh. “Lựa chọn” là vị trí của môn ở THPT.",
"w1-094":"Môn Tin học góp phần phát triển năng lực đặc thù là năng lực tin học, gồm 5 thành phần (NLa–NLe).",
"w1-095":"Tin học hỗ trợ các môn khác đổi mới phương pháp giáo dục, đánh giá và triển khai nội dung dạy học mới. Tin học không thay thế nội dung môn khác và không chỉ giới hạn trong phạm vi môn Tin học.",
"w1-096":"Vai trò đặc thù của CS là phát triển tư duy máy tính và các nguyên tắc thiết kế, phát triển hệ thống máy tính. Kĩ năng dùng phần mềm là ICT/DL; ý thức pháp luật, đạo đức là DL.",
"w1-097":"Phân hoá hai định hướng giúp đáp ứng năng lực, sở thích và định hướng nghề đa dạng của học sinh. Đây không phải phân luồng cố định hay tách thành hai môn độc lập.",
"w1-098":"NLb (ứng xử trong môi trường số) được phát triển tốt nhất khi học sinh tự thảo luận, phân tích tình huống và đề xuất cách ứng xử trước khi hành động. Liệt kê luật hay làm theo quy trình mẫu là thụ động.",
"w1-099":"Muốn xây dựng giải pháp bằng máy tính, phát triển hệ thống xử lí thông tin thì cần tập trung tư duy tính toán, thuật toán và lập trình, tức trọng tâm của định hướng Khoa học máy tính.",
"w3-001":"Bảy chủ đề chính là: Máy tính và xã hội tri thức; Mạng máy tính và Internet; Tổ chức lưu trữ, tìm kiếm và trao đổi thông tin; Đạo đức, pháp luật và văn hoá trong môi trường số; Ứng dụng tin học; Giải quyết vấn đề với sự trợ giúp của máy tính; Hướng nghiệp với tin học. “Trí tuệ nhân tạo và dữ liệu lớn” không phải một chủ đề chính.",
"w3-002":"Nội dung môn Tin học được xây dựng từ 3 mạch kiến thức: Học vấn số hoá phổ thông (DL), Công nghệ thông tin và truyền thông (ICT), Khoa học máy tính (CS).",
"w3-003":"Ở tiểu học, yêu cầu chỉ ở mức ban đầu: dùng máy tính hỗ trợ học tập, vui chơi và bước đầu thích ứng với thiết bị số thông minh. Tạo sản phẩm số, chuyển giao nhiệm vụ cho máy hay hiểu biết về bản quyền là yêu cầu của các cấp cao hơn.",
"w3-004":"CS trả lời câu hỏi “máy tính và chương trình hoạt động theo nguyên lí nào”. Cách ứng dụng máy tính là ICT; lợi ích xã hội và điều kiện phát triển công nghệ thuộc DL.",
"w3-005":"Năm phẩm chất chủ yếu là: yêu nước, nhân ái, chăm chỉ, trung thực, trách nhiệm. Tự chủ, sáng tạo, hợp tác là năng lực chung, không phải phẩm chất.",
"w3-006":"Mỗi cụm chuyên đề học tập lựa chọn ở THPT có thời lượng 35 tiết/năm học. Môn Tin học THPT có 70 tiết/năm cho phần cốt lõi và định hướng.",
"w3-007":"Năm phẩm chất chủ yếu là: yêu nước, nhân ái, chăm chỉ, trung thực, trách nhiệm. Các phương án khác thay vào “nhân nghĩa”, “cần kiệm”, “sáng tạo”… không đúng văn bản chương trình.",
"w3-008":"NLc là “Giải quyết vấn đề với sự hỗ trợ của CNTT-TT”. NLa là sử dụng, quản lí phương tiện; NLd là học và tự học; NLe là hợp tác.",
"w3-009":"Mỗi lớp ở THPT có cụm chuyên đề 35 tiết, gồm 3 chuyên đề với thời lượng 10, 10 và 15 tiết.",
"w3-010":"Ba mạch kiến thức là Học vấn số hoá phổ thông (DL), Công nghệ thông tin và truyền thông (ICT), Khoa học máy tính (CS).",
"w3-011":"Tổng hợp, tiếp thu ý kiến chuyên gia trong và ngoài nước là kinh nghiệm thực tế, nên thuộc căn cứ thực tiễn. Căn cứ pháp lí là văn bản pháp luật; căn cứ lí luận là các cơ sở khoa học giáo dục.",
"w3-012":"Yêu cầu cần đạt và nội dung giáo dục có quan hệ tương hỗ, biện chứng: một yêu cầu có thể gắn với nhiều nội dung, một nội dung góp phần vào nhiều yêu cầu.",
"w3-013":"Ba mạch cốt lõi là DL, ICT và CS. Trí tuệ nhân tạo (AI) chỉ là nội dung trong các chủ đề, không phải mạch kiến thức.",
"w3-014":"Đặc trưng của CS là vận dụng tư duy tính toán, thuật toán và lập trình để giải quyết vấn đề. Dùng công nghệ an toàn, ứng xử phù hợp là DL; lựa chọn, ứng dụng hệ thống máy tính là ICT.",
"w3-015":"Quan hệ là nhiều–nhiều: một yêu cầu cần đạt có thể gắn với nhiều nội dung, và một nội dung cũng có thể gắn với nhiều yêu cầu. Hai phương án chỉ nêu một chiều là chưa đầy đủ.",
"w3-016":"Chương trình GDPT 2018 quy định 5 phẩm chất chủ yếu: yêu nước, nhân ái, chăm chỉ, trung thực, trách nhiệm.",
"w3-017":"NLc (giải quyết vấn đề), NLd (học và tự học), NLe (hợp tác) góp phần trực tiếp vào ba năng lực chung: giải quyết vấn đề và sáng tạo, tự chủ và tự học, giao tiếp và hợp tác.",
"w3-018":"Mỗi cấp học trình bày bằng hai bảng: bảng nội dung giáo dục toàn cấp học, và bảng yêu cầu cần đạt cùng nội dung giáo dục ở từng lớp.",
"w3-019":"Mục tiêu cốt lõi của CS là phát triển tư duy máy tính để phân tích vấn đề theo cách tiếp cận tin học. Lựa chọn, áp dụng hệ thống là ICT; kĩ năng văn phòng và ứng xử số thuộc ICT/DL.",
"w3-020":"“Mạng máy tính và Internet” là một trong 7 chủ đề chính. Các phương án khác gần giống tên chủ đề nhưng sai chữ (tên đúng là “Tổ chức lưu trữ, tìm kiếm và trao đổi thông tin”, “Ứng dụng tin học”, “Đạo đức, pháp luật và văn hoá trong môi trường số”).",
"w3-021":"Trách nhiệm là một trong 5 phẩm chất chủ yếu. Tự chủ, giao tiếp, sáng tạo thuộc nhóm năng lực chung.",
"w3-022":"Năm thành phần năng lực tin học là NLa–NLe. Lắp ráp, sửa chữa phần cứng mạng không thuộc năng lực đặc thù của môn.",
"w3-023":"Nội dung môn Tin học được tổ chức thành 7 chủ đề xuyên suốt ba cấp học (từ chủ đề A đến G).",
"w3-024":"Chương trình môn Tin học có 3 mạch kiến thức: DL, ICT, CS. Số 7 là số chủ đề, số 5 là số thành phần năng lực.",
"w3-025":"Chủ đề G là “Hướng nghiệp với tin học”. Ứng dụng tin học là chủ đề E, Giải quyết vấn đề với sự trợ giúp của máy tính là F, Đạo đức, pháp luật… là D.",
"w3-026":"Ở THPT có hai định hướng: Tin học ứng dụng và Khoa học máy tính. Các phương án khác là tên nghề hoặc lĩnh vực hẹp.",
"w3-027":"Các nguyên lí và thực hành làm cơ sở để hiểu biết, mô hình hoá tính toán và phát triển hệ thống máy tính là định nghĩa của mạch Khoa học máy tính (CS).",
"w3-028":"Ở THCS, NLa yêu cầu sử dụng đúng cách các thiết bị, phần mềm thông dụng và mạng máy tính phục vụ học tập, cuộc sống. Nhận diện thiết bị là mức tiểu học; khai thác hệ điều hành nâng cao, chọn dịch vụ ICT là mức THPT hoặc thuộc thành phần khác.",
"w3-029":"Vai trò cốt lõi của CS là hình thành tư duy máy tính để hiểu nguyên lí hoạt động của hệ thống. Thành thạo phần mềm là ICT, pháp luật và ứng xử là DL.",
"w3-030":"Tách hai bảng giúp gắn kết mục tiêu (yêu cầu cần đạt) với việc lựa chọn kiến thức (nội dung giáo dục): giáo viên biết dạy nội dung nào để đạt yêu cầu nào.",
"w3-031":"Bảng nội dung giáo dục toàn cấp học cho thấy các chủ đề con được triển khai ở từng lớp trong cả cấp. Bảng yêu cầu cần đạt chỉ mô tả mức đạt ở từng lớp.",
"w3-032":"Yêu cầu cần đạt quy định độ rộng, độ sâu của nội dung, và hai yếu tố có quan hệ tương hỗ. Chúng không tương ứng một–một, cũng không độc lập nhau.",
"w3-033":"Ở tiểu học, yêu cầu chú trọng nhận biết, thực hành cơ bản và hình thành thói quen sử dụng an toàn. Vận dụng phức hợp, phân hoá định hướng, thiết kế giải pháp tích hợp là yêu cầu ở THPT.",
"w3-034":"Thời lượng chủ đề chỉ mang tính đề xuất, nên giáo viên chủ động điều chỉnh theo điều kiện thực tế. Việc này không cho phép thay đổi tổng số tiết của môn hay cắt giảm thực hành.",
"w3-035":"Năm thành phần năng lực chỉ phân biệt tương đối, chúng đan xen và bổ trợ nhau. Không phải mỗi năng lực ứng với một chủ đề hay một hoạt động riêng.",
"w3-036":"Ở THPT, khác biệt quan trọng là phân hoá theo định hướng nghề nghiệp, có yêu cầu cần đạt riêng cho Tin học ứng dụng và Khoa học máy tính. Các phương án khác mô tả chung, có thể đúng với cả THCS.",
"w3-037":"Mục đích phân hoá thành hai định hướng là đáp ứng định hướng nghề nghiệp của học sinh trong lĩnh vực tin học. Sở thích hay năng lực cá nhân chưa phải lí do chính được chương trình nêu.",
"w3-038":"Hợp tác trong môi trường số thể hiện rõ nhất khi nhóm vừa phân công hợp lí vừa chủ động trao đổi, hỗ trợ nhau trong suốt quá trình. Mỗi người tự làm phần mình rồi ghép lại thì chưa phải hợp tác thật sự.",
"w3-039":"Ba mạch hoà quyện: hiểu biết môi trường số (DL), chọn công nghệ phù hợp (ICT) và vận dụng tư duy tính toán (CS) cùng lúc. Các phương án khác đặt một mạch lên trên hoặc chỉ dùng “khi cần”.",
"w3-040":"Các thành phần năng lực liên quan chặt chẽ nên được phát triển đồng thời qua hoạt động học tập, không chọn một năng lực trọng tâm hay chia năng lực theo từng nhiệm vụ.",
"w3-041":"CS đề cập đến các nguyên lí và thực hành làm cơ sở hiểu biết, mô hình hoá tính toán, tư duy thuật toán, lập trình. Dùng phần mềm văn phòng là ICT, ứng xử và pháp luật là DL, tháo lắp phần cứng không thuộc mạch nào.",
"w3-042":"Thực hành và tạo sản phẩm số giúp học sinh vận dụng kiến thức, qua đó hình thành và phát triển năng lực tin học. Mục đích không phải giảm lí thuyết hay thành thạo một phần mềm cụ thể.",
"w3-043":"Hiểu chương trình là mô tả thuật toán bằng ngôn ngữ máy tính giúp học sinh nắm logic chương trình, khai thác ý tưởng thuật toán và hình thành tư duy giải quyết vấn đề. Yêu cầu này không nhằm ghi nhớ cú pháp.",
"w3-044":"Kết hợp DL, ICT và CS giúp học sinh huy động nhiều kiến thức, kĩ năng để thực hiện nhiệm vụ phù hợp. Ba mạch không tách theo cấp học, không thay thế nội dung cũ và không để học sinh tự chọn mạch.",
"w3-045":"Câu hỏi tìm quan điểm KHÔNG đúng. Các năng lực đan xen, bổ trợ nhau nên một hoạt động thường phát triển nhiều năng lực, không nên chỉ tập trung vào một thành phần.",
"w3-046":"Mục tiêu cốt lõi của CS là phát triển tư duy máy tính, hiểu nguyên lí hệ thống và thiết kế thuật toán. Hoà nhập môi trường số là DL; chọn và áp dụng phần mềm có sẵn là ICT.",
"w3-047":"Câu hỏi tìm nội dung KHÔNG thể hiện tính mở. Chương trình không bắt buộc dùng chung một ngôn ngữ lập trình; ngược lại, việc chọn ngôn ngữ, phần mềm là linh hoạt.",
"w3-048":"Video tri ân anh hùng liệt sĩ, “uống nước nhớ nguồn” thể hiện lòng biết ơn với Tổ quốc và truyền thống, tức phẩm chất yêu nước.",
"w3-049":"Bản chất biện chứng là quan hệ nhiều–nhiều: một yêu cầu cần đạt được hình thành từ nhiều chủ đề, và một chủ đề góp phần vào nhiều yêu cầu. Quan hệ một–một hay độc lập đều sai.",
"w3-050":"Tuân thủ “độ rộng và độ sâu” là xác định đúng phạm vi và mức độ yêu cầu, để thiết kế hoạt động vừa sức. Mở rộng tối đa hay tăng khối lượng kiến thức đều vi phạm nguyên tắc này.",
"w3-051":"ICT chú trọng thực hành tạo sản phẩm số bằng phần mềm thiết yếu; CS tăng cường kiến thức thuật toán, dữ liệu, lập trình, robot giáo dục. Các phương án khác đảo ngược hai định hướng hoặc gán sai đối tượng học.",
"w3-052":"Ngôn ngữ trực quan (kéo thả khối lệnh) giảm trở ngại về cú pháp, nhờ đó học sinh tập trung vào thuật toán, cách giải quyết vấn đề và ý tưởng lập trình, tức là cốt lõi của tư duy máy tính. Các phương án khác chỉ nêu lợi ích bề ngoài, hoặc sai khi cho rằng trực quan làm giảm yêu cầu phân tích.",
"w3-053":"Yêu cầu cần đạt định hướng giáo viên lựa chọn phương pháp dạy học và biên soạn công cụ kiểm tra, đánh giá. Nó không dùng để xếp loại thi đua giáo viên, cắt giảm lí thuyết hay áp một kịch bản chung.",
"w3-054":"Tư duy máy tính đặc trưng bởi phân rã, trừu tượng hoá, nhận diện mẫu và mô hình hoá để xây dựng giải pháp máy thực hiện được. Các phương án khác chỉ là thao tác, sử dụng công cụ hay câu lệnh.",
"w3-055":"Cụm chuyên đề ICT tăng cường thực hành tạo sản phẩm số ứng dụng; cụm CS chú trọng thiết kế thuật toán, lập trình. Hai định hướng không chia theo khối ngành, cũng không phải quản trị mạng, đồ hoạ hay lắp ráp phần cứng.",
"w3-056":"“Chạy thử được chương trình” ở lớp 5 chỉ cần học sinh chạy một chương trình hoàn chỉnh, nhập đầu vào và xem kết quả. Tìm lỗi, sửa khối lệnh hay giải thích kết quả là vượt mức yêu cầu.",
"w3-057":"Muốn khắc phục việc luyện thao tác đơn lẻ, cần giao nhiệm vụ gắn với tình huống thực tiễn, để học sinh tự xác định cách làm và chọn công cụ phù hợp. Chỉ tăng độ khó hay luyện thêm thao tác vẫn là dạy kĩ năng rời rạc.",
"w3-058":"Dự án lập trình nhỏ giải quyết bài toán thực tế đòi hỏi phân tích, thiết kế thuật toán, lập trình, kiểm thử và hợp tác, nên phát triển đồng thời nhiều năng lực. Sửa lỗi hay vẽ sơ đồ khối chỉ là một khâu riêng lẻ.",
"w3-059":"Dự án lập trình ứng dụng nhỏ cho bài toán thực tế giúp học sinh thật sự “chuyển giao nhiệm vụ cho máy tính” và phát triển nhiều năng lực cùng lúc. Học thuộc, làm trắc nghiệm hay chép mã chỉ là ghi nhớ thụ động.",
"w3-060":"Yêu cầu “Chạy thử được chương trình” chỉ cần học sinh tái hiện các bước để có kết quả sau khi nhập dữ liệu. Tự xây dựng chương trình, sửa lỗi hay giải thích kết quả là vượt yêu cầu, gây quá tải cho học sinh lớp 5.",
"w3-061":"NLb hình thành tốt nhất khi học sinh tự phân tích tình huống giả mạo thực tế, xây dựng tiêu chí nhận diện và đề xuất cách tự bảo vệ. Học thuộc luật, nghe giảng hay ghi chép quy trình chỉ là tiếp nhận thụ động.",
"w3-062":"Giáo dục ứng xử trong môi trường số cần để học sinh phân tích tình huống, xác định vấn đề (xâm phạm quyền riêng tư) và đề xuất cách ứng xử. Ghi nhớ quy định, làm theo số đông hay chỉ thao tác bảo mật đều chưa đúng định hướng.",
"w3-063":"Khi mạng yếu, cách chắc chắn nhất là lưu sẵn thông tin thiết yếu để tra cứu ngoại tuyến, kèm bản đồ, ảnh, thuyết minh. Bộ nhớ đệm, tải trước hay đồng bộ nền vẫn phụ thuộc vào việc từng có kết nối.",
"w3-064":"Cần kết hợp số liệu, hình ảnh và giải pháp thành một sản phẩm dễ theo dõi, nên phần mềm trình chiếu là phù hợp nhất. Bảng tính, xử lí ảnh hay soạn thảo văn bản chỉ đáp ứng một phần yêu cầu.",
"w3-065":"Nhiệm vụ có hai yêu cầu: thuận tiện tổng hợp và bảo vệ thông tin cá nhân. Chỉ phương án đúng nêu đủ cả việc chọn công nghệ, khai thác dữ liệu và bảo vệ thông tin; các phương án khác bỏ qua vế bảo mật.",
"w3-066":"Kết hợp tìm kiếm thông tin, hợp tác nhóm trực tuyến và đề xuất giải pháp sản phẩm giúp phát triển đồng thời nhiều năng lực (NLc, NLd, NLe…). Các phương án khác chỉ tập trung một kĩ năng hoặc làm theo mẫu.",
"w3-067":"Chương trình định hướng lấy vấn đề thực tế làm trung tâm để học sinh huy động, kết hợp kiến thức của các mạch cần thiết. Chia dự án máy móc theo DL/ICT/CS hay coi một mạch là chính đều đi ngược tinh thần ba mạch hoà quyện.",
"w3-068":"Với yêu cầu “Chạy thử được chương trình”, chỉ cần nhập dữ liệu vào chương trình có sẵn, chạy và quan sát kết quả. Thiết kế bộ kiểm thử, sửa lỗi thuật toán hay đọc mã để dự đoán là vượt mức lớp 5.",
"w3-069":"Yêu cầu cần đạt quy định độ rộng, độ sâu của nội dung, nên giáo viên phải đối chiếu yêu cầu cần đạt để chọn phạm vi kiến thức. Không chọn theo tài liệu chi tiết, theo số hoạt động hay theo đề kiểm tra.",
"w3-070":"Để rèn tự học và đánh giá thông tin, học sinh cần dùng AI để tìm kiếm, đối chiếu và chọn thông tin đáng tin cậy. Các phương án khác chọn theo độ phong phú hay hình thức, không có bước kiểm chứng.",
"w3-071":"Để hình thành phẩm chất, cần phân tích tình huống thực tế và gắn nội dung học với biểu hiện phẩm chất cần hình thành. Chỉ tập trung kiến thức, hoặc tách phẩm chất khỏi tình huống, đều chưa hiệu quả.",
"w3-072":"Nhóm học sinh không theo CNTT chuyên sâu, muốn thành thạo phần mềm để tạo sản phẩm số, nên phù hợp với cụm chuyên đề Tin học ứng dụng (ICT). CS thiên về thuật toán, lập trình; các phương án còn lại trái quy định chương trình.",
"w3-073":"Câu hỏi tìm quyết định KHÔNG đúng. Dùng thủ thuật tải lậu tài liệu có bản quyền là vi phạm pháp luật và thiếu trung thực, dù với mục đích học tập. Các cách còn lại (dùng học liệu mở, xin kinh phí, trích dẫn phần tóm tắt) đều hợp lệ.",
"w3-074":"Dùng nhạc miễn phí bản quyền hoặc xin phép tác giả là cách hợp pháp duy nhất. Mục đích học tập, cắt ngắn đoạn nhạc hay ghi tên tác giả đều không thay thế được việc xin phép khi chia sẻ công khai.",
"w3-075":"Xoá dấu bản quyền là vi phạm. Cách vừa giữ chất lượng vừa hợp pháp là xin phép tác giả, hoặc tìm ảnh thay thế có giấy phép chia sẻ tự do.",
"w3-076":"Theo chương trình, nên chọn bài toán phù hợp với kiến thức, kĩ năng liên môn mà học sinh đã có ở thời điểm đó. Như vậy vừa khả thi vừa đảm bảo yêu cầu cần đạt, không cần học bù trước hay giảm yêu cầu lập trình.",
"w3-077":"Ở THPT, học sinh cần tự đi qua quy trình đầy đủ: phân tích yêu cầu, chọn dữ liệu, phân chia nhiệm vụ, thiết kế thuật toán, lập trình, kiểm thử và điều chỉnh. Các phương án cung cấp sẵn quy trình hoặc làm theo mẫu đều làm giảm yêu cầu tư duy.",
"w3-078":"Chương trình khuyên chọn linh hoạt các bài toán vừa sức với kiến thức học sinh đã có ở các môn khác tại thời điểm đó. Dạy bù hay giao tài liệu chuyên sâu gây quá tải; để học sinh giỏi gánh nhóm thì không bảo đảm mọi em đạt yêu cầu.",
"w3-079":"NLb là “Ứng xử phù hợp trong môi trường số”. NLa là sử dụng, quản lí phương tiện; NLc là giải quyết vấn đề; NLe là hợp tác.",
"w3-080":"Quan hệ là nhiều–nhiều: một yêu cầu cần đạt hình thành từ nhiều chủ đề, một chủ đề góp phần vào nhiều yêu cầu. Gắn cố định, suy ra một chiều hay tách rời chức năng đều sai.",
"w3-081":"Đánh giá định kì tổng hợp yêu cầu cần đạt của các chủ đề đã học trong giai đoạn. Đánh giá thường xuyên bám yêu cầu chi tiết của bài; bài cuối cấp không chỉ bám chủ đề gần nhất; yêu cầu cần đạt do chương trình quy định, không do sách giáo khoa.",
"w3-082":"Để học sinh “trình bày và giải thích” được nội dung luật, cách tốt nhất là thảo luận và phân tích tình huống thực tiễn rồi liên hệ quy định. Trích số hiệu điều luật, vẽ sơ đồ cấu trúc luật hay học thuộc định nghĩa chỉ là ghi nhớ.",
"w3-083":"Dự án tích hợp nhiều nhiệm vụ nên cần đánh giá sự phát triển đồng thời nhiều thành phần năng lực qua các nhiệm vụ đó. Tách rời từng năng lực, chỉ chấm sản phẩm cuối hay chỉ ưu tiên hợp tác đều phiến diện.",
"w4-001":"Chương trình nêu rõ: nhiều chủ đề thuộc định hướng Khoa học máy tính phù hợp với phương pháp nêu và giải quyết vấn đề, nhằm phát triển mạnh tư duy máy tính.",
"w4-002":"Với mạch CS, đánh giá chú trọng năng lực sáng tạo và tư duy có tính hệ thống của học sinh. Vận dụng tạo sản phẩm là trọng tâm của ICT; thái độ, ứng xử là trọng tâm của DL.",
"w4-003":"Định hướng chung là chú trọng phương pháp dạy học trực quan và thực hành. Các phương án khác dùng từ tuyệt đối như “mọi nội dung”, “mọi chủ đề”, hoặc ghép sai phương pháp với loại bài.",
"w4-004":"Với ICT, đánh giá coi trọng khả năng vận dụng kiến thức, kĩ năng để tạo ra sản phẩm, không phải ghi nhớ lệnh hay thuộc quy trình thao tác.",
"w4-005":"Căn cứ đánh giá là yêu cầu cần đạt về phẩm chất và năng lực quy định trong chương trình. Số bài kiểm tra, phong trào thi đua hay số sản phẩm không phải căn cứ.",
"w4-006":"Dạy học theo dự án được khuyến khích để phát huy năng lực làm việc nhóm, năng lực tự học và tính chủ động của học sinh.",
"w4-007":"Phương pháp giáo dục phải được đối chiếu với các căn cứ pháp lí, khoa học và thực tiễn. Các phương án khác chỉ là yếu tố cụ thể của một bài dạy.",
"w4-008":"Phương pháp được ưu tiên cho định hướng Khoa học máy tính ở THPT là nêu và giải quyết vấn đề.",
"w4-009":"Định hướng phương pháp là tạo cơ hội để học sinh giải quyết vấn đề thực tiễn bằng cách trực tiếp tạo ra và thử nghiệm sản phẩm số. Dạy lí thuyết trước, dạy đồng loạt hay giảm ngữ cảnh thực tế đều trái định hướng.",
"w4-010":"Đánh giá mạch CS chú trọng năng lực sáng tạo và tư duy hệ thống. Tạo sản phẩm số là trọng tâm của ICT; giao tiếp, hợp tác không phải trọng tâm riêng của CS.",
"w4-011":"Theo chương trình, nhiều chủ đề của định hướng Khoa học máy tính phù hợp với phương pháp nêu và giải quyết vấn đề.",
"w4-012":"Phương pháp dự án được khuyến khích để phát huy năng lực làm việc nhóm, tự học và tính chủ động của học sinh.",
"w4-013":"Nội dung thực hành được tổ chức ở phòng máy tính để học sinh thao tác trực tiếp trên thiết bị.",
"w4-014":"Với mạch ICT, đánh giá coi trọng khả năng vận dụng kiến thức, kĩ năng để làm ra sản phẩm, không phải ghi nhớ định nghĩa hay trình bày quy trình.",
"w4-015":"Mục tiêu đánh giá là cung cấp thông tin chính xác để điều chỉnh hoạt động dạy và học. Xếp loại hay kiểm tra ghi nhớ không phải mục tiêu chính.",
"w4-016":"Căn cứ đánh giá là yêu cầu cần đạt về phẩm chất và năng lực trong chương trình. Kết quả kiểm tra là sản phẩm của đánh giá chứ không phải căn cứ.",
"w4-017":"Chương trình khuyến khích lập hồ sơ học tập dưới dạng cơ sở dữ liệu đơn giản để cập nhật kết quả đánh giá thường xuyên.",
"w4-018":"Nhiều chủ đề của định hướng CS phù hợp với dạy học nêu và giải quyết vấn đề, nhằm phát triển tư duy máy tính. Thực hành phần mềm và dự án sản phẩm số gần với ICT hơn.",
"w4-019":"Câu hỏi tìm yếu tố KHÔNG được căn cứ. Đánh giá diện rộng chỉ dựa vào yêu cầu cần đạt của phần bắt buộc, biểu hiện năng lực cốt lõi, phẩm chất và năng lực chung. Chủ đề, chuyên đề lựa chọn mỗi nơi học khác nhau nên không được dùng làm căn cứ.",
"w4-020":"Chương trình yêu cầu vận dụng phương pháp, hình thức tổ chức một cách linh hoạt theo đặc thù của từng bài học, nội dung cụ thể. Các phương án khác nêu căn cứ quá chung hoặc lệch trọng tâm.",
"w4-021":"Câu hỏi tìm nội dung KHÔNG thuộc định hướng. Định hướng chung gồm khai thác môi trường số, dạy học phân hoá, theo tình huống, trực quan và thực hành. “Chuyên môn hoá các môn học” không có trong định hướng.",
"w4-022":"Đánh giá thường xuyên dựa vào yêu cầu cần đạt của bài học, chủ đề, không dựa vào bộ đề chung hay năng khiếu.",
"w4-023":"Để phát triển NLa, chương trình khuyến khích phương pháp nhận dạng, thể hiện kết hợp với thực hành trên thiết bị và phần mềm.",
"w4-024":"Dạy học dự án, với nhiệm vụ học tập thực tiễn, được khuyến khích để phát huy làm việc nhóm, tự học và tính chủ động. Các phương án khác vẫn do giáo viên dẫn dắt hoặc truyền thụ.",
"w4-025":"Nhiều chủ đề của định hướng Khoa học máy tính phù hợp với dạy học nêu và giải quyết vấn đề, nhằm phát triển tư duy máy tính. Luyện theo mẫu, thuyết trình hay thực hành phần mềm không phải trọng tâm của định hướng này.",
"w4-026":"Yêu cầu “vận dụng để giải quyết vấn đề trong tình huống” được phản ánh khi xem cách học sinh xử lí một tình huống gần thực tiễn. Trình bày lại kiến thức, ghi nhớ khái niệm hay mô tả quy trình chỉ là mức nhớ, hiểu.",
"w4-027":"Đánh giá sản phẩm số tập trung vào mức độ dùng kiến thức, kĩ năng để tạo sản phẩm đáp ứng mục tiêu nhiệm vụ, không đi vào từng khái niệm, thao tác riêng lẻ.",
"w4-028":"Chương trình nhấn mạnh tính linh hoạt: lựa chọn phương pháp phù hợp với đặc thù từng bài học. Các phương án khác đúng một phần nhưng không nêu được tinh thần linh hoạt.",
"w4-029":"Với ICT, đánh giá tập trung vào khả năng tạo ra sản phẩm; với CS, đánh giá chú trọng tư duy hệ thống và sáng tạo. Hai mạch không khác nhau ở hình thức nhóm/cá nhân hay định tính/định lượng.",
"w4-030":"Đánh giá đồng đẳng chủ yếu nhằm phát triển tư duy phản biện, năng lực giao tiếp và hợp tác của học sinh. Mục đích không phải tạo cạnh tranh hay giúp giáo viên cho điểm.",
"w4-031":"Đánh giá vì sự tiến bộ là so sánh học sinh với chính mình ở giai đoạn trước, không so với bạn khác hay chỉ phân loại trình độ.",
"w4-032":"Theo triết lí “đánh giá như là học tập”, rubric và đánh giá đồng đẳng giúp học sinh thấy khoảng cách giữa năng lực hiện tại và chuẩn cần đạt, từ đó tự điều chỉnh việc học. Thi đua, chấm nhanh hay chuẩn hoá theo mẫu không phải giá trị của triết lí này.",
"w4-033":"ICT dùng phương pháp giúp học sinh vận dụng tổng hợp kiến thức để tạo sản phẩm số; CS chú trọng phát triển tư duy máy tính. Đây là cơ sở để chọn phương pháp chủ đạo khác nhau. Các phương án khác quy về thao tác phần mềm hay lí thuyết.",
"w4-034":"NLb liên quan thái độ, hành vi, nên cần kết hợp xử lí tình huống với quan sát hành vi thực tế mới phản ánh đúng ý thức tuân thủ chuẩn mực. Thao tác thiết bị, hiểu luật hay hợp tác nhóm không phải trọng tâm của NLb.",
"w4-035":"Đánh giá thường xuyên cung cấp thông tin kịp thời về sự tiến bộ của học sinh để điều chỉnh dạy học. Tổng hợp chất lượng sau giai đoạn là chức năng của đánh giá định kì.",
"w4-036":"Giáo viên quan sát và học sinh tự đánh giá là phối hợp nhiều chủ thể trong đánh giá, đúng như chương trình khuyến khích.",
"w4-037":"Chương trình nêu: nêu và giải quyết vấn đề phù hợp với nhiều chủ đề của định hướng Khoa học máy tính. Các nhận định khác ghép phương pháp với chủ đề không đúng văn bản.",
"w4-038":"Khi dùng sản phẩm số làm căn cứ, giáo viên xem mức độ học sinh vận dụng kiến thức, kĩ năng. Số thao tác hay thời gian hoàn thành không phản ánh năng lực.",
"w4-039":"Đánh giá qua sản phẩm số không chấm từng kiến thức rời rạc, vì mục tiêu là xem học sinh vận dụng kiến thức, kĩ năng ra sao để đáp ứng nhu cầu thực tế. Mục tiêu không phải giảm tải hay tự động hoá việc chấm.",
"w4-040":"Ngay cả nội dung nặng lí thuyết, chương trình vẫn định hướng thiết kế nhiệm vụ để học sinh chủ động khám phá, hình thành kiến thức. Các phương án khác đều lấy giáo viên trình bày làm trung tâm.",
"w4-041":"Sáng tạo là đề xuất cách giải quyết mới, rồi thử nghiệm và điều chỉnh. Vận dụng cái đã học, kết hợp cách đã biết hay sửa theo phản hồi là vận dụng, chưa phải sáng tạo.",
"w4-042":"Đánh giá qua sản phẩm số dựa vào khả năng vận dụng kiến thức, kĩ năng để đáp ứng yêu cầu nhiệm vụ thực tế, không tách rời kĩ năng hay đối chiếu thao tác.",
"w4-043":"Định hướng là đặt học sinh vào tình huống có vấn đề, để các em phân tích, trao đổi và tự khái quát thành thuật toán (nêu và giải quyết vấn đề). Làm theo hướng dẫn, đọc học liệu hay xem chương trình mẫu đều thụ động hơn.",
"w4-044":"Các nội dung thực hành của chủ đề E nên tổ chức ở phòng máy để học sinh thao tác trực tiếp trên phần mềm. Lí do không phải để giáo viên minh hoạ bài giảng.",
"w4-045":"Đối chiếu kết quả với yêu cầu cần đạt cho biết học sinh đáp ứng các tiêu chí đến đâu, từ đó có hướng hỗ trợ phù hợp. Đánh giá không nhằm làm cho mọi học sinh có kết quả như nhau.",
"w4-046":"Ở THPT, sản phẩm số được đòi hỏi cao hơn về mức độ hoàn thiện và khả năng ứng dụng vào thực tế. Số công cụ, thời gian hay độ chính xác thao tác không phải khác biệt bản chất.",
"w4-047":"Mạch ICT hướng tới kĩ năng dùng công cụ số tạo sản phẩm phục vụ đời sống, nên sản phẩm số là minh chứng tự nhiên nhất. Ứng xử là DL; thuật toán, phần mềm là CS.",
"w4-048":"Dạy học dự án được khuyến khích vì phát huy năng lực làm việc nhóm, tự học và tính chủ động của học sinh. Các phương án khác lấy sự thuận tiện của giáo viên làm lí do.",
"w4-049":"Đổi mới đánh giá là xem sản phẩm số hoàn thiện đến đâu trong việc đáp ứng yêu cầu của nhiệm vụ thực tế, không chỉ thẩm mĩ, thuyết trình hay số tính năng.",
"w4-050":"Đánh giá mạch DL theo hướng năng lực là quan sát thái độ, hành vi và cách học sinh xử lí tình huống trong môi trường số. Học thuộc luật, cài phần mềm hay lập trình không phản ánh năng lực ứng xử.",
"w4-051":"Bài thực hành tạo sản phẩm số được đánh giá qua chính sản phẩm và độ hoàn thiện so với nhiệm vụ thực tế. Thi lí thuyết hay chấm kĩ năng tách rời mục đích đều sai định hướng.",
"w4-052":"Đánh giá thường xuyên coi trọng nhận xét định tính, gắn với tiến trình học và không gây áp lực. Kiểm tra lấy điểm sau mỗi tiết hay học thuộc thì trái tinh thần này.",
"w4-053":"Với ICT, đánh giá coi trọng khả năng vận dụng kiến thức, kĩ năng làm ra sản phẩm số và độ hoàn thiện của sản phẩm, không phải thao tác lẻ hay mô tả quy trình.",
"w4-054":"Vì chương trình mở, kết quả đánh giá là cơ sở để điều chỉnh dạy học, quản lí và phát triển chương trình địa phương một cách linh hoạt, hiệu quả. Các phương án khác chỉ nói về học sinh hay sự thống nhất kiểm tra.",
"w4-055":"NLb cần được đánh giá bằng cách phối hợp xử lí tình huống cụ thể với quan sát thái độ, hành vi thực tế. Thi trắc nghiệm khẩu hiệu, lắp ráp phần cứng hay viết mã chặn web đều không đo đúng năng lực ứng xử.",
"w4-056":"Hồ sơ học tập dạng cơ sở dữ liệu đơn giản giúp chẩn đoán và theo dõi sự tiến bộ của từng học sinh trên trục phát triển năng lực, không tạo áp lực. Mục đích không phải thi đua, thay sổ điểm chính thức hay so sánh công khai.",
"w4-057":"Thực hành trên phần mềm tạo điều kiện để học sinh trực tiếp vận dụng kiến thức, hình thành năng lực thực hành. Mục đích không phải truyền đạt nhanh lí thuyết hay kiểm soát thao tác.",
"w4-058":"Đánh giá mạch CS chú trọng năng lực sáng tạo và tư duy có tính hệ thống. Tạo sản phẩm số là ICT, hành vi ứng xử là DL, “nắm vững kiến thức” chưa phải trọng tâm năng lực.",
"w4-059":"CS hướng tới các nguyên tắc của tư duy máy tính làm cơ sở thiết kế, phát triển hệ thống, nên cần đánh giá sáng tạo và tư duy hệ thống. Thao tác phần mềm là ICT, ứng xử là DL.",
"w4-060":"Với định hướng Tin học ứng dụng, phù hợp nhất là dự án nhóm tạo sản phẩm số phục vụ đời sống, vì vừa vận dụng tổng hợp vừa hợp tác. Làm theo tệp mẫu hay làm lại theo quy trình chỉ rèn thao tác.",
"w4-061":"Muốn học sinh linh hoạt với điều kiện mới, cần cho các em tự phân rã, trừu tượng hoá, thiết kế thuật toán và đánh giá giải pháp với bài toán mới. Giữ bài quen, viết mã ngay hay để giáo viên phân rã sẵn đều không rèn được tư duy.",
"w4-062":"Đánh giá NLb cần đặt học sinh vào tình huống vi phạm bản quyền cụ thể và quan sát thái độ, cách xử lí. Tranh luận pháp lí, bảng quy chuẩn hay phần mềm kiểm tra trùng lặp chưa đánh giá được ứng xử thực.",
"w4-063":"Quy trình phát huy tối đa năng lực: khảo sát thực tế, tạo sản phẩm, tự đánh giá kết hợp đánh giá đồng đẳng và tự hoàn thiện. Các phương án khác để giáo viên nghiệm thu, chấm điểm một chiều.",
"w4-064":"Câu hỏi gợi mở yêu cầu học sinh tự giải thích ý nghĩa các bước giúp các em hiểu quy trình, từ đó tự học được. Xem lại thao tác, làm theo trí nhớ hay thêm sơ đồ vẫn là làm theo máy móc.",
"w4-065":"Minh chứng rõ nhất về năng lực giải quyết vấn đề là để học sinh tự chọn vấn đề thực tế, xây dựng và kiểm thử chương trình, rồi giải thích cách giải quyết. Các phương án khác thiếu bước gắn với thực tế hoặc thiếu bước kiểm thử, giải thích.",
"w4-066":"Đối chiếu sản phẩm của nhau theo rubric đã công bố là đánh giá quá trình (đồng đẳng): giúp các nhóm kịp thời cải tiến mà không tạo áp lực thi cử. Nhật kí, tự đánh giá để xếp loại hay trắc nghiệm hằng tuần không đáp ứng đủ.",
"w4-067":"Đánh giá phải dựa trên mức độ đáp ứng yêu cầu nhiệm vụ và việc vận dụng kiến thức để giải quyết vấn đề thực tế. Vì vậy nhóm 2 được đánh giá cao hơn dù sản phẩm đơn giản; hình thức, thẩm mĩ không phải tiêu chí chính.",
"w4-068":"Kiểm tra giấy không phải hình thức bắt buộc. Giáo viên cần đối chiếu yêu cầu cần đạt với năng lực cần đánh giá để chọn hình thức, công cụ phù hợp (thực hành, sản phẩm, dự án…). Các phương án còn lại vẫn chỉ quanh bài kiểm tra viết.",
"w4-069":"Học sinh làm đúng từng thao tác nhưng không làm được nhiệm vụ mới, tức là thiếu khả năng vận dụng tổng hợp. Vì vậy cần thiết kế nhiệm vụ đánh giá việc vận dụng tổng hợp kiến thức, kĩ năng, không chia nhỏ theo từng yêu cầu hay từng bước.",
"w4-070":"Các nhóm có thế mạnh khác nhau, nên cách công bằng là đối chiếu sản phẩm với yêu cầu nhiệm vụ và mức độ hoàn thành các tiêu chí đã xác định trước. Các phương án khác chỉ chọn vài khía cạnh theo cảm tính.",
"w4-071":"Năng lực ứng xử thể hiện qua hành vi, nên cần bổ sung tình huống để quan sát cách học sinh lựa chọn và thực hiện hành vi trong môi trường số. Cộng điểm kiến thức với điểm sản phẩm không đo được ứng xử.",
"w4-072":"Năng lực “Ứng xử phù hợp trong môi trường số” được đánh giá qua cách xử lí tình huống và hành vi cụ thể, không qua thi tự luận, học thuộc khẩu hiệu hay ghi nhớ chế tài.",
"w4-073":"Đề 100% trắc nghiệm lí thuyết chỉ kiểm tra tái hiện, đồng nhất tri thức kĩ thuật với năng lực, trong khi môn Tin học cần đánh giá khả năng vận dụng tạo sản phẩm số. Các phương án khác nêu lí do không chính xác.",
"w4-074":"Để đánh giá năng lực thực chất ở chủ đề E, cần cho học sinh tạo sản phẩm số (trình chiếu, sơ đồ tư duy, bảng tính) và xem mức độ đáp ứng nhiệm vụ thực tế. Trắc nghiệm, chấm theo bài mẫu hay kiểm tra miệng vẫn là học thuộc, tái hiện.",
"w4-075":"Bài toán mở, để học sinh tự tìm hiểu bản chất, xây dựng ý tưởng và tự kiểm chứng, giúp tránh làm theo khuôn mẫu. Các phương án khác đều cung cấp sẵn thuật toán, phương án hoặc thao tác mẫu.",
"w4-076":"Điểm định kì chưa phản ánh đủ năng lực vận dụng. Giáo viên nên bổ sung hoạt động thực hành trong các tiết học và dùng kết quả để điều chỉnh nhận định. Chỉ dựa vào điểm, hoặc lấy trung bình cộng, đều chưa chính xác.",
"w4-077":"Dạy học phân hoá: giao cùng đề tài nhưng cho chọn mức nâng cao khác nhau. Như vậy mọi học sinh đạt yêu cầu cốt lõi, còn học sinh khá giỏi được phát triển thêm. Tách nhóm cứng nhắc hay giao cùng một bài cơ bản đều không đáp ứng cả hai mục tiêu.",
"w4-078":"Đánh giá theo năng lực xem cả kết quả giải quyết bài toán lẫn cách học sinh xây dựng, tổ chức, hoàn thiện chương trình (dùng hàm, chú thích). Chỉ nhìn kết quả, hay chỉ nhìn hình thức mã, đều phiến diện.",
"w4-079":"Rubric toàn diện bao quát nhiều thành phần năng lực: kĩ thuật tạo sản phẩm số (NLc), trích dẫn nguồn và bảo mật cá nhân (NLb) và hợp tác nhóm (NLe). Các phương án khác dùng tiêu chí định lượng hình thức như số trang, dung lượng, tốc độ.",
"w4-080":"Gắn với vấn đề thực tế thì giải pháp phải được kiểm chứng hiệu quả qua sản phẩm số. Trình bày lí thuyết hay mô tả các bước chưa chứng minh được giải pháp có hiệu quả.",
"w4-081":"Đánh giá cung cấp thông tin về mức độ đáp ứng yêu cầu cần đạt và sự tiến bộ của học sinh, để điều chỉnh dạy học.",
"w4-082":"Theo định hướng năng lực, đặt kết quả từng thời điểm cạnh yêu cầu cần đạt tương ứng để thấy sự thay đổi, tức là so với chuẩn và với chính học sinh. Các phương án khác thiếu chuẩn đối chiếu là yêu cầu cần đạt.",
"w4-083":"Chương trình nêu: các chủ đề (như lập trình) thuộc định hướng Khoa học máy tính phù hợp với phương pháp nêu và giải quyết vấn đề. Ưu tiên đàm thoại lí thuyết, thực hành theo mẫu hay dùng chung một nhóm phương pháp đều sai.",
"w4-084":"Đánh giá NLb cần để học sinh phân tích tình huống, chọn cách ứng xử và giải thích căn cứ quyết định. Nhận diện luật hay trình bày nguyên tắc mới chỉ dừng ở mức biết.",
"w4-085":"Với mạch ICT, đánh giá định kì phù hợp nhất là giao xây dựng trang web giải quyết nhu cầu thực tế, rồi chấm độ hoàn thiện so với yêu cầu. Thi tự luận, làm giống mẫu hay chấm kĩ năng lẻ đều không đánh giá được năng lực.",
"w5-001":"Thông tư 32/2020/TT-BGDĐT ban hành Điều lệ trường THCS, trường THPT và trường phổ thông có nhiều cấp học. Thông tư 32/2018 ban hành Chương trình GDPT; Công văn 5512 hướng dẫn kế hoạch giáo dục.",
"w5-002":"Ở THPT, mỗi học sinh chọn 3 cụm chuyên đề học tập của 3 môn học (mỗi cụm 35 tiết/năm).",
"w5-003":"Hoạt động trải nghiệm, hướng nghiệp ở THPT có 105 tiết/năm học (3 tiết/tuần).",
"w5-004":"Kế hoạch giáo dục nhà trường cho phép linh hoạt khi tổ chức thực hiện, nhờ đó trường chủ động điều chỉnh cách triển khai chương trình theo điều kiện thực tế.",
"w5-005":"Theo hướng dẫn, quy trình gồm: xây dựng khung kế hoạch thời gian, các tổ chuyên môn xây dựng kế hoạch dạy học, hiệu trưởng hoàn thiện và ban hành.",
"w5-006":"Kế hoạch giáo dục nhà trường là văn bản quan trọng nhất, chi phối kế hoạch của tổ chuyên môn và kế hoạch bài dạy của giáo viên.",
"w5-007":"Theo Chương trình GDPT 2018 (bản ban hành ban đầu), học sinh THPT chọn 5 môn từ 3 nhóm môn lựa chọn, mỗi nhóm ít nhất 1 môn. Lưu ý: Thông tư 13/2022 đã điều chỉnh thành chọn 4 môn.",
"w5-008":"Quy trình phân tích hoạt động học gồm: mô tả hành động của học sinh, đánh giá kết quả, rồi phân tích nguyên nhân học sinh học được hay chưa học được (bước 3), sau đó mới đưa biện pháp.",
"w5-009":"Đây là đáp án theo tài liệu nguồn. Lưu ý: Chương trình Hoạt động trải nghiệm, hướng nghiệp 2018 nêu 4 loại hình chủ yếu là sinh hoạt dưới cờ, sinh hoạt lớp, hoạt động giáo dục theo chủ đề và sinh hoạt câu lạc bộ, nên bạn nên đối chiếu thêm với giảng viên.",
"w5-010":"Kế hoạch giáo dục nhà trường là cấp độ quan trọng nhất, trực tiếp chi phối kế hoạch dạy học của tổ và của từng giáo viên.",
"w5-011":"Quản trị nhà trường theo chu trình: xây dựng kế hoạch, tổ chức thực hiện, kiểm tra và giám sát, điều chỉnh và hoàn thiện.",
"w5-012":"Ở bước xây dựng khung kế hoạch thời gian, hiệu trưởng chủ trì họp với các bên liên quan. Tổ trưởng chủ trì ở bước tổ chuyên môn lập kế hoạch.",
"w5-013":"Kế hoạch giáo dục nhà trường là việc tổ chức hoạt động giáo dục theo chương trình và theo điều kiện cụ thể của nhà trường. Các phương án khác chỉ là một bộ phận của kế hoạch.",
"w5-014":"Tính khoa học, sư phạm là nội dung sắp xếp theo trình tự hợp lí, bảo đảm thống nhất và liên kết. Khai thác cơ sở vật chất, huy động lực lượng, phù hợp địa phương thuộc các yêu cầu khác.",
"w5-015":"Hiệu trưởng chịu trách nhiệm hoàn thiện và ban hành kế hoạch giáo dục nhà trường.",
"w5-016":"Kế hoạch giáo dục phải bảo đảm tính pháp lí theo các văn bản hiện hành. Trường không được ưu tiên hoạt động ngoài chương trình hay thay đổi mục tiêu giáo dục.",
"w5-017":"Về tiến trình kiến thức, kế hoạch phải bảo đảm tính logic và sự thống nhất giữa các môn học, hoạt động giáo dục, không đòi đồng nhất phương pháp hay hình thức.",
"w5-018":"Trình tự đúng: xây dựng khung thời gian, xây dựng kế hoạch môn học (tổ chuyên môn), rồi hoàn thiện kế hoạch (hiệu trưởng).",
"w5-019":"Kế hoạch giáo dục nhà trường được xem là cấp độ quan trọng nhất, vì đây là nơi chương trình quốc gia được cụ thể hoá thành hoạt động thực tế.",
"w5-020":"Môn Tin học ở THPT có 70 tiết/năm học (2 tiết/tuần), chưa kể 35 tiết chuyên đề học tập.",
"w5-021":"Kế hoạch giáo dục nhà trường cần huy động nhà trường, gia đình và các lực lượng cộng đồng xã hội. Các phương án khác chỉ gồm lực lượng trong trường.",
"w5-022":"Giáo viên góp ý xây dựng kế hoạch, trực tiếp thực hiện, phối hợp các lực lượng và đánh giá hiệu quả. Phê duyệt, ban hành là việc của hiệu trưởng.",
"w5-023":"Theo quy định về định mức tiết dạy (đáp án của tài liệu nguồn), giáo viên trung học được tính tối thiểu 17 tiết/tuần khi dạy liên kết hoặc được phân công nhiệm vụ.",
"w5-024":"Ở bước 1 (khung kế hoạch thời gian), hiệu trưởng tổ chức họp với các thành phần liên quan.",
"w5-025":"Rà soát kế hoạch cần bảo đảm tính logic của mạch kiến thức, sự thống nhất giữa các môn và tổng thời lượng đúng quy định. Không được điều chỉnh mục tiêu chương trình theo từng lớp.",
"w5-026":"Câu hỏi tìm nội dung KHÔNG phải yêu cầu. Kế hoạch phải phù hợp điều kiện, linh hoạt, khả thi và gắn với mục tiêu phát triển phẩm chất, năng lực học sinh; không lấy kinh nghiệm hay định hướng riêng của giáo viên làm trọng tâm.",
"w5-027":"Đây là đáp án theo tài liệu nguồn. Lưu ý: theo Chương trình tổng thể, mỗi cụm chuyên đề của một môn là 35 tiết/năm (học sinh chọn 3 cụm, tổng 105 tiết), nên bạn nên đối chiếu thêm.",
"w5-028":"Bốn loại hình chủ yếu của hoạt động trải nghiệm, hướng nghiệp là: sinh hoạt dưới cờ, sinh hoạt lớp, hoạt động giáo dục theo chủ đề, sinh hoạt câu lạc bộ. “Sinh hoạt văn hoá, văn nghệ” không nằm trong bốn loại hình này.",
"w5-029":"Văn bản kế hoạch giáo dục nhà trường có bảng tổng hợp chung các môn học, hoạt động giáo dục (số tiết theo khối lớp), do hiệu trưởng tổng hợp.",
"w5-030":"Cơ sở vật chất và đặc điểm học sinh là căn cứ để chọn và tổ chức các hoạt động giáo dục phù hợp thực tế, bảo đảm tính khả thi.",
"w5-031":"Để kế hoạch đồng bộ và khả thi, hiệu trưởng lấy ý kiến các tổ chuyên môn, phân bổ hợp lí nguồn lực và hoàn thiện dự thảo trước khi ban hành.",
"w5-032":"Dự giờ trong nghiên cứu bài học tập trung phân tích hoạt động học của học sinh để điều chỉnh phương pháp, hình thức tổ chức. Mục đích không phải đánh giá, xếp loại giáo viên.",
"w5-033":"Giáo viên chủ nhiệm xây dựng kế hoạch hoạt động phù hợp với đặc điểm học sinh lớp mình và phối hợp tổ chức thực hiện. Thống nhất kế hoạch toàn trường không phải vai trò chính của họ.",
"w5-034":"Nguyên tắc là kết hợp nhu cầu học sinh với nguồn lực thực tế: khảo sát nhu cầu rồi thiết kế tổ hợp môn khả thi. Giữ nguyên mọi nguyện vọng thì không khả thi; ép học sinh theo danh mục định sẵn hay chỉ mở môn đông người thì bỏ qua nhu cầu.",
"w5-035":"Kế hoạch giáo dục nhà trường cụ thể hoá chương trình, lựa chọn nội dung và cách tổ chức phù hợp với điều kiện thực tế của trường. Chỉ dạy theo tiến trình sách giáo khoa là không đủ.",
"w5-036":"Mục tiêu, nội dung, phương pháp liên kết logic và phù hợp tâm sinh lí, nhận thức học sinh chính là biểu hiện của tính khoa học và tính sư phạm.",
"w5-037":"Tổ chuyên môn xây dựng kế hoạch dạy học các môn và phân công giáo viên dựa trên khung thời gian chung. Ban hành khung thời gian, phê duyệt là việc của hiệu trưởng; kế hoạch bài dạy do từng giáo viên soạn.",
"w5-038":"Dự giờ theo nghiên cứu bài học tập trung quan sát, phân tích hoạt động học của học sinh để rút kinh nghiệm, không nhằm đánh giá, xếp loại giáo viên.",
"w5-039":"Số tiết không nhất thiết chia đều mỗi tuần; tiến độ môn học có thể sắp theo tiến trình chung của năm học, miễn đủ tổng thời lượng.",
"w5-040":"Nhà trường được phân phối thời gian linh hoạt theo điều kiện thực tế, nhưng phải bảo đảm đủ thời lượng và yêu cầu của chương trình. Không được ưu tiên hay cắt giảm môn theo điều kiện.",
"w5-041":"Rà soát đội ngũ giáo viên trước hết để xác định khả năng triển khai các môn học, hoạt động giáo dục theo chương trình (môn nào mở được, cần liên kết hay không).",
"w5-042":"Khảo sát trước giúp nhà trường có dữ liệu thực tế để chuẩn bị phương án nhân sự, cơ sở vật chất và xếp lớp phù hợp.",
"w5-043":"Phân phối thời gian linh hoạt giúp trường chủ động bố trí kế hoạch phù hợp với đội ngũ và cơ sở vật chất. Trường không được tự ý thay đổi nội dung hay yêu cầu cần đạt.",
"w5-044":"Cần xây dựng phương án vừa phù hợp mục tiêu giáo dục vừa phù hợp nguồn lực thực tế. Các phương án khác lấy nhu cầu riêng của từng tổ, từng môn làm căn cứ.",
"w5-045":"Chú ý điều kiện thực tế để việc tổ chức chương trình phù hợp với nguồn lực và đặc điểm của từng cơ sở giáo dục, bảo đảm tính khả thi.",
"w5-046":"Tìm hiểu nguyện vọng trước là để xác định nhu cầu người học, từ đó chuẩn bị nhân lực và cơ sở vật chất phù hợp.",
"w5-047":"Bảo đảm tính logic nghĩa là khi điều chỉnh vẫn giữ trình tự kiến thức hợp lí và sự liên kết giữa các nội dung.",
"w5-048":"Tính khoa học, sư phạm gồm: trình tự kiến thức hợp lí, thống nhất giữa các môn và hoạt động, và phân bổ thời gian phù hợp. Chia thời gian “đồng đều” không phải yêu cầu.",
"w5-049":"Không bắt buộc chia đều theo tuần là để bảo đảm tính khoa học sư phạm và khai thác hiệu quả nguồn lực (phòng máy, giáo viên). Mục đích không phải dạy nhanh để ôn thi hay giảm yêu cầu cần đạt.",
"w5-050":"Chất lượng chuyên môn của kế hoạch thể hiện ở việc bố trí thời lượng linh hoạt mà vẫn bảo đảm logic kiến thức. Ngân sách hay định mức giờ dạy là vấn đề quản lí.",
"w5-051":"Giáo viên tham gia xây dựng và thực hiện kế hoạch giúp kế hoạch khả thi trong thực tiễn và triển khai hiệu quả hơn. Giáo viên không quyết định mục tiêu giáo dục của trường.",
"w5-052":"Trường khó khăn được điều chỉnh tiến độ theo điều kiện, nhưng vẫn phải bảo đảm yêu cầu cần đạt của các môn. Thay đổi nội dung hay ưu tiên môn này, bỏ môn kia là sai nguyên tắc.",
"w5-053":"Cân nhắc cả người học và nhà trường để hài hoà giữa mục tiêu phát triển năng lực và tính khả thi khi triển khai. Điều kiện dạy học không được chi phối yêu cầu cần đạt.",
"w5-054":"Khi đăng kí vượt khả năng, cần kết hợp nhu cầu của học sinh với điều kiện thực tế của nhà trường, không đặt riêng một phía lên trước.",
"w5-055":"Câu hỏi tìm nhận định KHÔNG đúng. Nhà trường được bố trí linh hoạt, không bắt buộc chia đều số tiết các môn trong đúng 35 tuần. Các nhận định còn lại đều đúng hướng dẫn.",
"w5-056":"Khảo sát trước để có thông tin về nguyện vọng học sinh, làm căn cứ tổ chức các nhóm môn phù hợp với điều kiện của trường. Khảo sát không dùng để thay đổi nội dung hay môn học của chương trình.",
"w5-057":"Nghiên cứu bài học hướng tới việc học của học sinh: làm rõ điều học sinh chưa làm được, tìm nguyên nhân và đề xuất cách khắc phục. Mục đích không phải quy trách nhiệm hay đánh giá giáo viên.",
"w5-058":"Kế hoạch giáo dục nhà trường do hiệu trưởng ban hành, cụ thể hoá khung thời gian và tổ chức chung; kế hoạch dạy học của tổ do tổ trưởng chủ trì xây dựng, cụ thể hoá chương trình từng môn.",
"w5-059":"Trình tự phân tích bài học: mô tả hành động học của học sinh, đánh giá kết quả, phân tích nguyên nhân, rồi đưa biện pháp khắc phục.",
"w5-060":"Chương trình là cơ sở định hướng (pháp lệnh); sách giáo khoa là tài liệu cung cấp nội dung cụ thể để giáo viên lựa chọn cách triển khai phù hợp. Không bắt buộc giữ nguyên trình tự sách.",
"w5-061":"Bản chất tính khoa học, sư phạm là tiến trình bài học logic và sự thống nhất liên môn. Tuân thủ văn bản là tính pháp lí; khảo sát nhu cầu, huy động lực lượng là yêu cầu khác.",
"w5-062":"Cắt giảm tuỳ tiện thời lượng môn cơ bản phá vỡ trình tự, sự cân đối của mạch kiến thức, nên vi phạm tính khoa học và sư phạm (theo đáp án tài liệu). Việc này đồng thời cũng trái quy định về thời lượng.",
"w5-063":"Vai trò đầy đủ của giáo viên: góp ý xây dựng kế hoạch, trực tiếp triển khai, phối hợp các lực lượng, đánh giá và đề xuất điều chỉnh. Các phương án khác chỉ nêu một phần, hoặc coi giáo viên là người thực thi thụ động.",
"w5-064":"“Tính khoa học, sư phạm” thể hiện rõ nhất ở tính logic của mạch kiến thức và sự liên kết giữa các môn, hoạt động. Đúng văn bản là tính pháp lí; khai thác cơ sở vật chất là tính khả thi.",
"w5-065":"Tính pháp lí là bảo đảm mọi hoạt động đúng văn bản chỉ đạo, quy định hiện hành. Dựa vào quy định để “điều chỉnh nội dung” là sai.",
"w5-066":"Xem xét học sinh, giáo viên, cơ sở vật chất để chọn nội dung, hình thức tổ chức phù hợp thực tế, đồng thời vẫn bảo đảm mục tiêu phát triển phẩm chất, năng lực. Không phải để giảm yêu cầu hay đồng loạt hoá.",
"w5-067":"Làm mất tính logic của mạch kiến thức là vi phạm tính khoa học trong tổ chức, sắp xếp nội dung giáo dục, dù có thể vẫn linh hoạt, thực tiễn.",
"w5-068":"Hoạt động mới cần được cập nhật chính thức vào kế hoạch giáo dục và điều chỉnh phân phối thời gian. Làm trước rồi bổ sung hồ sơ, hay lồng ghép tuỳ tiện, đều không đúng quy trình.",
"w5-069":"Cách đúng là điều chỉnh phương án tổ chức dựa trên kết quả khảo sát, đồng thời cân đối đội ngũ và cơ sở vật chất. Giữ nguyên, tăng sĩ số quá mức hay bỏ qua nguyện vọng đều không phù hợp.",
"w5-070":"Khi hoạt động linh hoạt bị trùng lịch, cần rà soát kế hoạch thời gian chung và điều chỉnh thời điểm tổ chức. Giữ nguyên rồi để giáo viên tự xoay xở, hay cắt bớt hoạt động, đều không giải quyết gốc vấn đề.",
"w5-071":"Nghiên cứu bài học tập trung vào học sinh: phân tích nguyên nhân từ cách học sinh tiếp nhận nhiệm vụ để điều chỉnh cách tổ chức. Phương án đúng không nhằm nhận xét kĩ năng của giáo viên.",
"w5-072":"Mỗi lớp cần 70 tiết. Học 5 tiết/tuần trong 14 tuần là đủ 70; 14 tuần nằm gọn trong học kì I (18 tuần) và học kì II (17 tuần), mỗi thời điểm chỉ 4 lớp dùng phòng. Các phương án khác chỉ đạt 65 tiết (13 tuần × 5) hoặc cần 34 tuần trong một học kì 18 tuần.",
"w5-073":"Phương án phù hợp: giáo viên Tin học phụ trách cụm chuyên đề đúng cấu trúc (các chuyên đề 10 hoặc 15 tiết, tổng 35 tiết), bố trí linh hoạt, mời chuyên gia doanh nghiệp hỗ trợ phần hướng nghiệp. Giao hẳn cho doanh nghiệp, chia 7 chuyên đề 5 tiết, hay bắt cả khối học đều sai.",
"w5-074":"Chia hai nhóm 4 lớp, mỗi lớp 2 tiết/tuần trong 35 tuần là đủ 70 tiết, và mỗi thời điểm phòng máy chỉ phục vụ 4 lớp (2 nhóm × 2 tiết = 4 tiết phòng máy/tuần). Học dồn 70 tiết vào một học kì sẽ vượt quỹ 4 tiết phòng máy mỗi tuần.",
"w5-075":"Khi kết quả khảo sát khác dự kiến, cần điều chỉnh phương án tổ chức theo kết quả khảo sát, đồng thời cân đối giáo viên và cơ sở vật chất. Giữ nguyên, hay chỉ nghiêng về một phía, đều chưa phù hợp.",
"w5-076":"Giá trị cốt lõi của nghiên cứu bài học là quan sát, mô tả cụ thể hành động học của học sinh để phân tích nguyên nhân và điều chỉnh. Các phương án khác tập trung vào tỉ lệ đúng, thiết kế của giáo viên hay khó khăn của giáo viên.",
"w5-077":"Điều chỉnh đúng là phân tích kết quả và nguyên nhân chưa đạt, rồi sửa nội dung chưa phù hợp trong kế hoạch. Chỉ đổi lịch hay chỉ tổng hợp ý kiến thì chưa xử lí nguyên nhân.",
"w5-078":"Trùng phòng học bộ môn thì cần rà soát phương án, đối chiếu nhu cầu dùng phòng với thời khoá biểu và cân đối nguồn lực trước khi quyết định. Ưu tiên cảm tính một môn là chưa hợp lí.",
"w5-079":"Cách vừa đúng quy định vừa khả thi là xây dựng các tổ hợp môn hợp lí, công khai phương án ưu tiên và hướng dẫn học sinh điều chỉnh lựa chọn. Để giáo viên dạy trái chuyên môn, hay không mở môn, là sai.",
"w5-080":"Cải tiến dựa trên đánh giá: xác định điểm cần cải thiện và xây dựng phương án triển khai phù hợp hơn. Duy trì như cũ hay chỉ dựa vào kinh nghiệm không giải quyết được vấn đề.",
"w5-081":"Khi không có di tích và kinh phí hạn chế, có thể dạy trên lớp kết hợp xây dựng chủ đề phù hợp điều kiện địa phương, vẫn bảo đảm đủ nội dung. Tự ý đổi nội dung, hay đẩy cho học sinh tự tìm hiểu ngoài giờ, là không phù hợp.",
"w5-082":"Có thể bố trí thực hành theo từng giai đoạn (không chia đều mỗi tuần), miễn đủ tổng số tiết trong hai học kì. Cắt giảm thực hành, bắt học sinh mua máy, hay dồn hết sang học kì II đều sai quy định hoặc không khả thi.",
"w5-083":"Thiếu máy thì bố trí thực hành theo nhóm và điều chỉnh hình thức dạy học cho phù hợp số thiết bị. Giữ nguyên kế hoạch, hay chuyển nội dung thành lí thuyết, đều không khai thác hiệu quả điều kiện.",
"w5-084":"Cần căn cứ nguyện vọng học sinh để xây dựng phương án tổ chức phù hợp điều kiện thực tế. Chốt cố định theo số lớp, theo đa số, hay ép học sinh vào phương án dự kiến sẵn đều bỏ qua một phía.",
"w5-085":"Cựu học sinh chia sẻ kinh nghiệm thực tế, kết hợp với nhiệm vụ học tập do giáo viên tổ chức: vừa khai thác nguồn lực xã hội vừa giữ vai trò của giáo viên. Giao nội dung chính cho khách mời, hay tách thành hoạt động rời, đều không phù hợp.",
"w5-086":"Vẫn có thể bố trí một hoạt động tìm hiểu tại làng nghề trong thời lượng đã có, rồi xử lí kết quả trên lớp, vì làng nghề ở gần trường và tốn ít kinh phí. Học sinh được trải nghiệm thực tiễn mà không vượt thời lượng.",
"w5-087":"Trường thiếu phòng máy và giáo viên được bố trí dạy theo từng học kì (không chia đều) và liên kết với giáo viên trường khác. Giảm tổng thời lượng, hay chờ tuyển đủ người mới dạy, đều trái quy định.",
"w5-088":"Trường ở xa di tích, nên tăng cường tiết học trên lớp kết hợp học liệu số, giảm trải nghiệm thực địa, vẫn bảo đảm nội dung giáo dục địa phương. Tập trung vào ngoại khoá thì không khả thi; lồng ghép toàn bộ hay giao cho giáo viên chủ nhiệm là không đúng quy định.",
"w5-089":"Hoạt động trải nghiệm là nội dung bắt buộc. Nhà trường cần giải thích mục tiêu giáo dục toàn diện và điều chỉnh tiến độ ôn tập hợp lí, không cắt bỏ hoạt động trải nghiệm.",
"w5-090":"Giáo viên và người có kinh nghiệm thực tiễn cùng xây dựng, triển khai nội dung chuyên đề, phát huy thế mạnh của cả hai mà không làm mất vai trò giáo viên. Giao hẳn cho người ngoài là không phù hợp.",
"w5-091":"Cần giải thích mục tiêu giáo dục toàn diện, giữ đủ số tiết bắt buộc theo quy định và điều chỉnh tiến độ ôn tập hợp lí. Cắt giảm, hay phân bổ lại thời lượng hoạt động bắt buộc, đều trái quy định.",
"w5-092":"Phân bổ tiết thực hành theo tiến trình dạy học, đồng thời bố trí lịch phòng bộ môn dựa trên điều kiện thực tế. Dồn thực hành, để lịch phòng chi phối tiến trình, hay bắt môn khác nhường đều không hợp lí.",
"w6-001":"Câu hỏi tìm nội dung KHÔNG thuộc phân tích tình hình. Phân tích đặc điểm tình hình gồm học sinh, đội ngũ giáo viên, thiết bị và phòng bộ môn. Kế hoạch huy động nguồn lực xã hội là một phần kế hoạch, không phải phân tích tình hình.",
"w6-002":"Kế hoạch dạy học môn học của tổ bao gồm việc xác định nội dung và thời điểm các bài kiểm tra, đánh giá định kì. Hoàn thiện, phê duyệt kế hoạch nhà trường là việc của hiệu trưởng.",
"w6-003":"Chuẩn nghề nghiệp giáo viên cơ sở giáo dục phổ thông được quy định tại Thông tư 20/2018/TT-BGDĐT. Thông tư 32/2018 ban hành chương trình; Thông tư 22/2021 quy định đánh giá học sinh THCS, THPT.",
"w6-004":"Tính linh hoạt là sẵn sàng điều chỉnh nội dung và thời gian thực hiện khi điều kiện thực tế thay đổi. Dựa vào văn bản là tính pháp lí; trình tự kiến thức là tính logic; phù hợp cơ sở vật chất là tính khả thi.",
"w6-005":"Trình tự: phân tích đặc điểm tình hình, xây dựng kế hoạch dạy học, xây dựng kế hoạch tổ chức hoạt động giáo dục, rồi rà soát và hoàn thiện.",
"w6-006":"Phần “Đặc điểm tình hình” mô tả số lượng, trình độ đội ngũ và thiết bị dạy học (cùng số lớp, số học sinh). Phân phối thời lượng và kiểm tra định kì thuộc phần kế hoạch dạy học.",
"w6-007":"Bước đầu tiên là phân tích đặc điểm tình hình nhà trường và tổ chuyên môn. Có hiểu điều kiện thì mới lập kế hoạch khả thi.",
"w6-008":"Tính linh hoạt là cho phép điều chỉnh nội dung và thời gian khi thực tiễn thay đổi. Làm đúng trình tự từ đầu năm là ngược với linh hoạt; căn cứ văn bản là tính pháp lí.",
"w6-009":"Đánh giá cơ sở vật chất là lập danh mục thiết bị dạy học và phòng học bộ môn có thể sử dụng.",
"w6-010":"Khi triển khai kế hoạch đã phê duyệt, giáo viên nắm rõ nhiệm vụ được phân công và tiến độ thực hiện. Quyết định mục tiêu, phê duyệt hay ban hành quy định không phải việc của giáo viên.",
"w6-011":"Kế hoạch giáo dục của tổ chuyên môn gồm hai thành phần: kế hoạch dạy học môn học và kế hoạch tổ chức các hoạt động giáo dục (theo Phụ lục I Công văn 5512).",
"w6-012":"Trình tự: phân tích đặc điểm tình hình, xây dựng kế hoạch dạy học, xây dựng kế hoạch hoạt động giáo dục, rồi rà soát và hoàn thiện kế hoạch.",
"w6-013":"Bước đầu tiên theo Công văn 5512 là phân tích đặc điểm tình hình: đội ngũ, số học sinh, cơ sở vật chất, điều kiện dạy học.",
"w6-014":"Kế hoạch giáo dục của tổ gồm kế hoạch dạy học các môn học và kế hoạch tổ chức các hoạt động giáo dục.",
"w6-015":"Bốn yêu cầu khi xây dựng kế hoạch của tổ là: tính pháp lí, tính khả thi, tính logic và tính linh hoạt.",
"w6-016":"Hai thành phần cốt lõi là kế hoạch dạy học và kế hoạch tổ chức các hoạt động giáo dục. Kế hoạch cá nhân và kế hoạch bài dạy do từng giáo viên lập.",
"w6-017":"Với công tác quản lí, kế hoạch của tổ là cơ sở để theo dõi, đôn đốc và đánh giá việc thực hiện nhiệm vụ. Nó không thay kế hoạch của Bộ và không dùng để tự quyết kinh phí.",
"w6-018":"Theo đáp án của tài liệu, ý nghĩa quan trọng của quy trình là bước thống kê số liệu và đánh giá đặc điểm tình hình. Bước này cung cấp căn cứ thực tế để toàn bộ kế hoạch triển khai khả thi.",
"w6-019":"Thành phần kế hoạch giáo dục của tổ gồm kế hoạch dạy học môn học và kế hoạch tổ chức các hoạt động giáo dục.",
"w6-020":"Phù hợp với đặc điểm học sinh và đội ngũ giáo viên là biểu hiện của tính khả thi.",
"w6-021":"Tính khả thi là phân tích điều kiện thực tế của tổ và trường để lập kế hoạch phù hợp. Tuân thủ văn bản là tính pháp lí; trình tự hợp lí là logic; điều chỉnh khi thay đổi là linh hoạt.",
"w6-022":"Giáo viên thành viên trực tiếp xây dựng kế hoạch hoặc góp ý để hoàn thiện kế hoạch của tổ. Tổ chức xây dựng, phân công, theo dõi là nhiệm vụ của tổ trưởng.",
"w6-023":"Tổ trưởng theo dõi, kiểm tra việc thực hiện kế hoạch và phối hợp giải quyết vấn đề phát sinh. Cụ thể hoá thành kế hoạch cá nhân hay góp ý là việc của giáo viên.",
"w6-024":"Tổ điều chỉnh thời lượng chủ đề so với khung để phù hợp yêu cầu cần đạt và điều kiện thực tế của trường, không phải để chia đều cho dễ quản lí.",
"w6-025":"Không phân tích thiết bị trước thì kế hoạch có thể thiếu tính khả thi, nhất là các bài thực hành (ví dụ không đủ máy). Các hệ quả khác không bắt nguồn trực tiếp từ việc bỏ qua thiết bị.",
"w6-026":"Số tiết mỗi bài phụ thuộc chủ yếu vào số lượng và mức độ của các yêu cầu cần đạt. Thứ tự sách, thói quen cũ hay nguyện vọng học sinh không phải căn cứ quyết định.",
"w6-027":"Thời lượng từng bài dựa trên tổng thời lượng môn học, tỉ lệ các mạch nội dung và mức độ yêu cầu cần đạt. Chia đều theo sách hay theo định mức giờ dạy là không khoa học.",
"w6-028":"Linh hoạt là chủ động điều chỉnh phương pháp, hình thức khi điều kiện thay đổi mà vẫn đạt mục tiêu bài học. Lược bỏ nội dung, đổi thời lượng theo cảm tính hay đổi trình tự chủ đề cho tiện là sai.",
"w6-029":"Liên kết hợp lí: bài học sắp theo mạch kiến thức, các đợt đánh giá được phối hợp với kế hoạch chung của trường. Để lịch kiểm tra chi phối bài học, hay bỏ qua lịch trường, đều chưa hợp lí.",
"w6-030":"Tổ trưởng điều phối, các thành viên đóng góp trực tiếp hoặc qua góp ý. Như vậy kế hoạch có sự tham gia thật sự, không áp đặt từ một người.",
"w6-031":"Khi cơ sở vật chất chưa đáp ứng, cần điều chỉnh hoạt động cho phù hợp nguồn lực, vẫn giữ mục tiêu. Không được giảm yêu cầu cần đạt, giữ nguyên khi không khả thi, hay dồn sang kì sau.",
"w6-032":"Không xem xét học sinh, giáo viên, thiết bị thì tính khả thi bị hạn chế rõ nhất, vì chưa cân nhắc nguồn lực và điều kiện triển khai.",
"w6-033":"Xem xét điều kiện thực tế giúp chọn hình thức dạy học phù hợp với yêu cầu chương trình và nguồn lực. Không được điều chỉnh yêu cầu cần đạt hay giảm tổng số tiết.",
"w6-034":"Cả tổ cùng tham gia để tạo đồng thuận và thống nhất khi xác định mục tiêu, nhiệm vụ chung của năm học.",
"w6-035":"Thực hành luân phiên theo nhóm giúp vẫn đáp ứng yêu cầu cần đạt dù thiết bị hạn chế, nên mọi học sinh đều được thực hành.",
"w6-036":"Kế hoạch của tổ chuyển định hướng tổng thể của chương trình, nhà trường thành nhiệm vụ chuyên môn cụ thể, làm cơ sở để giáo viên lập kế hoạch cá nhân và bài dạy. Vì vậy nó là “nhịp cầu nối”.",
"w6-037":"Thời điểm tham quan nên khớp với tiến trình học các nội dung liên quan, để học sinh vận dụng kiến thức vào thực tế. Chọn theo tuần dự trữ hay theo hoạt động Đoàn là không gắn với nội dung học.",
"w6-038":"Câu hỏi tìm nhận định KHÔNG đúng. Phân phối chương trình không bắt buộc chia đều số tiết các bài trong đúng 35 tuần; số tiết phụ thuộc yêu cầu cần đạt và có thể bố trí linh hoạt.",
"w6-039":"Gắn thời điểm tổ chức hoạt động với nội dung dạy học là để học sinh có cơ hội vận dụng kiến thức, kĩ năng vừa học vào thực tiễn.",
"w6-040":"Khi thiết kế lại bài học từ sách giáo khoa, nguyên tắc pháp lí là phải thực hiện đầy đủ yêu cầu cần đạt quy định trong chương trình. Sách giáo khoa có thể thay đổi, còn yêu cầu cần đạt thì không.",
"w6-041":"Tổ trưởng nên tìm hiểu nguyên nhân, tư vấn giáo viên cải tiến phương pháp và giám sát tiến trình. Hạ chỉ tiêu cả khối, giữ nguyên hay đẩy sang kì sau đều không giải quyết được vấn đề.",
"w6-042":"Kế hoạch đã phê duyệt thì muốn thay đổi phải có minh chứng và trình cấp quản lí xem xét, phê duyệt. Tự ý cắt bài, tự thoả thuận với đồng nghiệp, hay dạy tiếp theo phân phối không phù hợp đều sai quy trình.",
"w6-043":"Để kế hoạch khả thi, tổ cần kiểm tra tình trạng thiết bị, tìm nguồn bổ sung, thay thế, và cụ thể hoá phương án dạy linh hoạt cho từng bài. Chỉ chia ca, chỉ đề xuất mua sắm, hay chuyển thực hành thành lí thuyết đều chưa đủ hoặc sai.",
"w6-044":"Thiếu tiết thì rà lại yêu cầu cần đạt, điều chỉnh cách tổ chức và phân phối thời lượng trong phạm vi cho phép. Dạy bù ngoài giờ, bỏ kiểm tra định kì hay dồn bài sang học kì II đều làm sai cấu trúc chương trình.",
"w6-045":"Câu lạc bộ nên có các chủ đề phân hoá: vừa củng cố thực hành ứng dụng vừa có nội dung nâng cao theo nhu cầu, phù hợp phát triển năng lực toàn diện. Dành toàn bộ cho học sinh giỏi là phiến diện.",
"w6-046":"Trùng tuần kiểm tra định kì thì cần dời sang thời điểm phù hợp trong kế hoạch chung, vẫn gắn logic với nội dung đã học. Tổ chức vào cuối tuần, để từng lớp tự chọn, hay thay bài kiểm tra đều không hợp lí.",
"w6-047":"Lịch trùng và học sinh chưa học nội dung nền, nên cần rà soát tiến trình dạy học, trao đổi với nhà trường và đơn vị tiếp đón để thống nhất phương án. Giữ nguyên lịch, hay bỏ tham quan, đều chưa giải quyết đúng.",
"w6-048":"Khi máy hỏng, tổ cần rà soát thiết bị hiện có, điều chỉnh cách tổ chức thực hành và đề xuất bổ sung điều kiện. Giữ nguyên kế hoạch hay chuyển thực hành thành lí thuyết đều không bảo đảm yêu cầu cần đạt.",
"w6-049":"Lịch kiểm tra trùng thì cần đối chiếu kế hoạch đánh giá giữa các môn và phối hợp điều chỉnh theo kế hoạch chung của trường. Các phương án khác chỉ thay đổi nội bộ môn Tin học, không giải quyết việc trùng lịch.",
"w6-050":"Theo Công văn 5512, tổ được thiết kế lại bài học thành chủ đề, miễn bảo đảm yêu cầu cần đạt của chương trình và trình hiệu trưởng phê duyệt trước khi thực hiện. Không cần trình cơ quan cấp trên.",
"w6-051":"Tổ trưởng nên căn cứ điều kiện nhà trường, xác định nội dung, mục tiêu từng bài, cân đối thời gian và rà soát tính khả thi. Các phương án khác dựa vào trình tự sách hay độ khó, chưa xử lí cả thiết bị lẫn yêu cầu cần đạt.",
"w6-052":"Phòng máy hạn chế thì xếp lịch thực hành luân phiên; giáo viên không đồng đều thì phân công giáo viên nòng cốt hỗ trợ. Tăng tổng số tiết, chuyển thực hành về nhà hay dời sang học kì II đều trái quy định hoặc không khả thi.",
"w6-053":"Giáo viên chưa hiểu nhiệm vụ thì tổ trưởng cần trao đổi để làm rõ nhiệm vụ, trách nhiệm và thống nhất cách triển khai. Đây là xử lí trực tiếp nguyên nhân; các phương án khác đi vòng hoặc để giáo viên tự xoay xở.",
"w6-054":"Cân đối lại phân phối chương trình và sắp thời gian thực hành theo điều kiện phòng máy, lịch chung: vừa khả thi vừa giữ logic. Đẩy lí thuyết lên trước hay ưu tiên theo khối có thể phá vỡ trình tự kiến thức.",
"w6-055":"Góp ý có trách nhiệm là tự nghiên cứu tài liệu, trao đổi với đồng nghiệp có kinh nghiệm, rồi đưa ý kiến có cơ sở chuyên môn. Chép kế hoạch cũ hay theo ý người khác là chưa làm tròn trách nhiệm.",
"w7-001":"Theo Công văn 5512, mỗi hoạt động trình bày theo thứ tự: Mục tiêu, Nội dung, Sản phẩm, Tổ chức thực hiện.",
"w7-002":"Khung kế hoạch bài dạy cấp THCS, THPT được hướng dẫn tại Công văn 5512/BGDĐT-GDTrH (Phụ lục IV). Công văn 2345 và 1315 là của cấp tiểu học.",
"w7-003":"Bước 2 là xác định chuỗi hoạt động học: chọn đơn vị kiến thức trọng tâm và dự kiến thời lượng cho từng hoạt động. Xác định yêu cầu cần đạt là bước 1; thiết kế nhiệm vụ, phiếu học tập là bước 3; rà soát là bước 4.",
"w7-004":"Mỗi hoạt động gồm 4 bước: chuyển giao nhiệm vụ, thực hiện nhiệm vụ, báo cáo và thảo luận, kết luận và nhận định. Mở đầu, hình thành kiến thức… là chuỗi hoạt động của cả bài, không phải các bước trong một hoạt động.",
"w7-005":"Trước khi dạy, cần rà soát mục tiêu, nội dung, phương pháp, phương tiện dạy học để bảo đảm thống nhất và khả thi. Điểm số hay thời khoá biểu không thuộc bản thiết kế bài dạy.",
"w7-006":"Chuỗi hoạt động theo Công văn 5512: Mở đầu, Hình thành kiến thức mới, Luyện tập, Vận dụng.",
"w7-007":"Kế hoạch bài dạy là bản thiết kế của giáo viên, thể hiện sự chủ động, sáng tạo trong chọn phương pháp và tổ chức hoạt động phù hợp với học sinh. Nó không phải văn bản pháp quy cứng nhắc hay bản chép nội dung sách giáo khoa.",
"w7-008":"Mỗi hoạt động có đủ 6 thành phần: tên hoạt động, thời gian, mục tiêu, nội dung, sản phẩm dự kiến, cách thức tổ chức. Phương án thiếu thời gian hoặc thay sản phẩm bằng phương tiện là chưa đúng.",
"w7-009":"Bước 1 (chuyển giao nhiệm vụ) trình bày cụ thể nhiệm vụ giao cho học sinh và thiết bị, học liệu sử dụng. Dự kiến khó khăn thuộc bước 2; tổ chức báo cáo thuộc bước 3; phân tích sản phẩm để kết luận thuộc bước 4.",
"w7-010":"Trình tự: xác định mục tiêu bài dạy, xác định chuỗi hoạt động học và mục tiêu từng hoạt động, xây dựng hoạt động cụ thể, hoàn thiện kế hoạch bài dạy.",
"w7-011":"Chuỗi hoạt động học gồm: Mở đầu, Hình thành kiến thức mới, Luyện tập, Vận dụng.",
"w7-012":"Kế hoạch bài dạy là “kịch bản” mô tả mục tiêu, thiết bị, học liệu và tiến trình tổ chức hoạt động dạy học của một bài. Nó không phải bản tổng hợp kết quả hay tài liệu tự học.",
"w7-013":"Quy trình: xác định mục tiêu bài dạy, xác định chuỗi hoạt động học, xây dựng hoạt động cụ thể, hoàn thiện kế hoạch. Mục tiêu luôn được xác định trước tiên.",
"w7-014":"Kế hoạch bài dạy giúp thiết lập môi trường dạy học phù hợp với mục tiêu. Nó không thay chương trình, không ép thống nhất phương pháp hay buộc mọi học sinh đạt kết quả như nhau.",
"w7-015":"Tiến trình dạy học một bài: Mở đầu, Hình thành kiến thức mới, Luyện tập, Vận dụng.",
"w7-016":"Hoạt động vận dụng chủ yếu được giao để học sinh thực hiện ngoài lớp học (ở nhà, ngoài giờ), vận dụng kiến thức vào thực tiễn.",
"w7-017":"Mục tiêu được viết theo biểu hiện phẩm chất, năng lực của học sinh (học sinh làm được gì), không theo nội dung sách hay hoạt động của giáo viên.",
"w7-018":"Mỗi hoạt động học cần có: tên hoạt động, thời gian, mục tiêu, nội dung, sản phẩm dự kiến và cách thức tổ chức cụ thể.",
"w7-019":"Bốn bước theo thứ tự: chuyển giao nhiệm vụ, thực hiện nhiệm vụ, báo cáo và thảo luận, kết luận và nhận định. Phải thực hiện trước rồi mới báo cáo, báo cáo trước rồi mới kết luận.",
"w7-020":"Câu hỏi tìm điều KHÔNG phải vai trò. Kế hoạch bài dạy không thể thay thế Chương trình GDPT; chương trình là căn cứ pháp lí để xây dựng kế hoạch bài dạy.",
"w7-021":"“Kế hoạch bài dạy” là tên gọi hiện nay của giáo án lên lớp của giáo viên.",
"w7-022":"Câu hỏi tìm hình thức KHÔNG thuộc đánh giá thường xuyên. Hỏi đáp, bài viết, thực hành, thí nghiệm, thuyết trình, sản phẩm học tập đều là đánh giá thường xuyên; thi giữa kì là đánh giá định kì.",
"w7-023":"Kế hoạch bài dạy là bản thiết kế chi tiết tiến trình tổ chức hoạt động dạy học, do chính giáo viên xây dựng. Phân phối thời lượng thuộc kế hoạch của tổ.",
"w7-024":"Sáu thành tố của mỗi hoạt động: tên hoạt động, thời gian thực hiện, mục tiêu, nội dung, sản phẩm dự kiến, cách thức tổ chức.",
"w7-025":"Phương tiện dạy học phải phù hợp với tiến trình tổ chức các hoạt động học của học sinh, nghĩa là phục vụ hoạt động học, không chỉ theo danh mục hay phần mềm sẵn có.",
"w7-026":"Mục tiêu tốt dùng động từ cụ thể, đo được, và mô tả hoạt động học của học sinh, không mô tả hành vi của giáo viên, không liệt kê tràn lan.",
"w7-027":"Sản phẩm là kết quả học sinh làm ra khi thực hiện nhiệm vụ, làm căn cứ để thảo luận, đánh giá và kết luận kiến thức, kĩ năng.",
"w7-028":"Trước tiên phải xác định kết quả học tập mong đợi (mục tiêu) dựa trên yêu cầu chương trình; sau đó mới chọn nội dung, chia thời lượng và chọn phương tiện.",
"w7-029":"Kế hoạch bài dạy không có khuôn mẫu duy nhất, nhờ đó thể hiện được ý tưởng dạy học linh hoạt của giáo viên để tổ chức hoạt động phù hợp với học sinh. Điều này không cho phép dạy ngoài chương trình hay truyền thụ một chiều.",
"w7-030":"Mỗi hoạt động bắt buộc có mục tiêu, nội dung, sản phẩm và tổ chức thực hiện. Thiếu sản phẩm và cách tổ chức là chưa đủ cấu trúc của một hoạt động học.",
"w7-031":"Không dự kiến tình huống học sinh gặp khó hay làm xong sớm cho thấy kế hoạch chưa chuẩn bị kĩ, thiếu tính linh hoạt và phương án dự phòng.",
"w7-032":"Dự kiến sản phẩm, câu trả lời của học sinh giúp giáo viên định hướng thảo luận và có căn cứ để kết luận kiến thức, kĩ năng.",
"w7-033":"Cách đánh giá trong mỗi hoạt động phải căn cứ vào mục tiêu của hoạt động đó và mục tiêu bài học. Nội dung, thời lượng hay thiết bị không phải căn cứ chính.",
"w7-034":"Để ứng phó diễn biến thực tế, cần cân nhắc đặc điểm học sinh, điều kiện dạy học và các tình huống có thể phát sinh. Các phương án khác là thành phần của thiết kế, chưa nói đến tính thích ứng.",
"w7-035":"Thuyết trình ở hầu hết hoạt động là đơn điệu. Cần kết hợp nhiều phương pháp, kĩ thuật, hình thức tổ chức phù hợp với mục tiêu từng hoạt động.",
"w7-036":"Yêu cầu về chuẩn bị là nghiên cứu kĩ đối tượng học sinh và điều kiện cơ sở vật chất để điều chỉnh kịch bản linh hoạt. Các phương án khác là yêu cầu về cấu trúc, đánh giá hay phương pháp.",
"w7-037":"Kết hợp hoạt động cá nhân, nhóm và cả lớp tạo cơ hội để học sinh làm nhiều loại nhiệm vụ và tương tác nhiều hơn khi học. Mục đích không phải để giáo viên kiểm soát hay làm cho mọi học sinh học giống nhau.",
"w7-038":"Kế hoạch bài dạy là bản thiết kế hướng dẫn, vì tiến trình có thể điều chỉnh linh hoạt theo diễn biến thực tế và nhu cầu học sinh. Lí do không phải sách thay đổi hay yêu cầu cần đạt giảm.",
"w7-039":"Hoạt động học tích cực tạo điều kiện để học sinh trải nghiệm, thực hành, khám phá kiến thức và phát triển năng lực. Các phương án khác lấy sự thuận tiện của giáo viên làm trung tâm.",
"w7-040":"Xác định cụ thể thiết bị, học liệu giúp bảo đảm điều kiện triển khai, hỗ trợ học sinh học và nâng cao chất lượng dạy. Mục đích không phải phục vụ kiểm tra hồ sơ hay thống kê.",
"w7-041":"Phẩm chất và năng lực chung được đánh giá bằng ghi nhận sự tiến bộ và nhận xét, dùng kết quả phù hợp với mục tiêu bài học. Chấm điểm phẩm chất mỗi tiết hay đưa vào bài kiểm tra lí thuyết là không phù hợp.",
"w7-042":"Xác định mục tiêu phẩm chất, năng lực giúp thiết kế hoạt động đúng trọng tâm và bao quát yêu cầu cần đạt. Giáo viên không được điều chỉnh yêu cầu cần đạt.",
"w7-043":"Năng lực chỉ hình thành khi người học tự huy động kiến thức, kĩ năng để giải quyết nhiệm vụ thực tiễn. Vì vậy phải chuyển sang tổ chức hoạt động học chủ động, không chỉ tăng ghi nhớ hay tốc độ tiếp thu.",
"w7-044":"Yêu cầu cần đạt được chuyển thành nhiệm vụ cụ thể khi học sinh phải làm, ví dụ thảo luận và viết chương trình thực hiện thuật toán tìm kiếm. Ghi chép mốc lịch sử, cam kết nội quy hay học thuộc cú pháp không phải nhiệm vụ phát triển năng lực.",
"w7-045":"Xây dựng chuỗi hoạt động giúp hình dung tổng thể phương án dạy học và bảo đảm giải quyết trọn vẹn các mục tiêu đề ra. Mục đích không phải thống nhất hình thức hay cố định thời lượng.",
"w7-046":"Cân đối tiến trình là phân bổ thời lượng hợp lí giữa các hoạt động, bảo đảm liên kết và hướng tới mục tiêu bài học. Mục đích không chỉ là dạy đủ nội dung hay tăng thời gian thực hành.",
"w7-047":"Lớp chênh lệch năng lực thì cần nhiệm vụ phân hoá theo mức độ: hỗ trợ học sinh còn khó khăn và có phần mở rộng cho học sinh khá. Giữ một nhiệm vụ chung, hay dạy theo nhóm yếu, đều bỏ quên một bộ phận học sinh.",
"w7-048":"Máy hỏng thì điều chỉnh phân nhóm và phân vai (thiết kế dữ liệu, thao tác máy) để mọi học sinh vẫn tham gia và vẫn đạt mục tiêu. Chỉ xem mẫu, chuyển sang lí thuyết hay ngồi chờ đều làm mất mục tiêu thực hành.",
"w7-049":"Theo hướng dẫn (Công văn 5512), giáo viên chọn một số nhóm trình bày theo mục đích sư phạm đã dự kiến, vừa tiết kiệm thời gian vừa có căn cứ nhận xét. Không cần mọi nhóm đều trình bày.",
"w7-050":"Học sinh thụ động trong nhóm thì cần thiết kế nhiệm vụ và phân công vai trò cụ thể cho từng em. Tăng thời gian, chuyển sang giáo viên trình bày hay thêm câu hỏi cuối giờ đều không khắc phục được nguyên nhân.",
"w7-051":"Đáp ứng khác biệt bằng phân hoá nhiệm vụ: phiếu hướng dẫn cho học sinh cần hỗ trợ, nhiệm vụ mở rộng cho em đã xong. Hạ tiêu chí cả lớp, hay chỉ để bạn giúp bạn, đều chưa đầy đủ.",
"w7-052":"Rút kinh nghiệm từ lớp trước để điều chỉnh hoạt động và phương pháp tổ chức cho phù hợp học sinh. Các phương án khác chỉ thêm hướng dẫn, thêm thời gian hay thêm kiểm tra, chưa xử lí nguyên nhân.",
"w7-053":"Khi hạn chế thiết bị và năng lực, giáo viên điều chỉnh nhiệm vụ, phương pháp, học liệu phù hợp thực tế nhưng vẫn bảo đảm yêu cầu cần đạt. Tinh giản nội dung là làm giảm yêu cầu.",
"w7-054":"Phương án đúng thể hiện đủ 4 bước: giao phiếu học tập (chuyển giao), quan sát và hỗ trợ nhóm (thực hiện), mời đại diện báo cáo (báo cáo, thảo luận), chốt kiến thức (kết luận). Các phương án khác là chép mã, đọc lệnh hay tự học không có thảo luận.",
"w7-055":"Hoạt động vận dụng cần thời gian thực tế (thu thập chi tiêu một tuần), nên giao làm ở nhà, nêu rõ cách nộp và tiêu chí đánh giá. Hạ yêu cầu hay bỏ hoạt động làm mất ý nghĩa vận dụng.",
"w7-056":"Chưa có phòng máy thì vẫn dạy được tư duy lập trình: thảo luận nhóm, viết thuật toán và chương trình trên giấy. Chuyển hết thành lí thuyết cú pháp, tạm dừng dạy hay giao tự học đều không đảm bảo yêu cầu.",
"w7-057":"Giao bài nâng cao cho học sinh xong sớm và để các em hướng dẫn bạn: vừa phân hoá vừa phát huy tính tích cực. Bắt ngồi chờ hay giảm yêu cầu chung đều không phù hợp.",
"w7-058":"Ở bước “Thực hiện nhiệm vụ”, giáo viên hỗ trợ bằng câu hỏi gợi ý để học sinh tự tìm và sửa lỗi. Sửa hộ, đưa mã chuẩn hay dừng cả lớp giảng lại đều làm học sinh mất cơ hội tự học.",
"w7-059":"Nội dung dài, thời lượng ít thì tinh giản nhiệm vụ trên lớp và chuyển hoạt động vận dụng phù hợp ra ngoài lớp. Tăng giảng giải, cắt bài tập hay kéo sang tiết sau đều không hợp lí.",
"w7-060":"Tiêu chí đánh giá cụ thể, công bố trước, kèm nhận xét chi tiết khi thực hành giúp học sinh tự điều chỉnh để tiến bộ. Bảng điểm công khai hay kiểm tra đáp án cố định chỉ nhằm xếp loại.",
"w7-061":"Phù hợp nhất: nhiệm vụ nhóm có mức hỗ trợ phù hợp, luân phiên dùng máy và có phương án hỗ trợ khi gặp khó. Như vậy vừa đáp ứng chênh lệch năng lực vừa phù hợp thiết bị hạn chế.",
"w7-062":"Kế hoạch bài dạy là kịch bản mô tả mục tiêu, thiết bị, học liệu và tiến trình dạy học của một bài. Phân phối cả năm là kế hoạch của tổ; thống nhất cho cả khối là sai bản chất.",
"w7-063":"Sau bước thực hiện nhiệm vụ là báo cáo kết quả và thảo luận; sau đó giáo viên mới kết luận, nhận định.",
"w7-064":"Mục tiêu bài học căn cứ vào yêu cầu cần đạt của chương trình và năng lực hiện tại của học sinh, không dựa vào thứ tự sách hay định mức giờ dạy.",
"w7-065":"“Hiểu được” không phải sản phẩm quan sát hay đo được, nên giáo viên thiếu căn cứ để nhận xét, đánh giá. Sản phẩm nên là thứ cụ thể, ví dụ đoạn chương trình dùng câu lệnh lặp hay câu trả lời phiếu học tập.",
"w7-066":"Đặt tình huống tính giá vé rồi hỏi “làm sao để máy tự chọn” là hoạt động Mở đầu, nhằm xác định vấn đề và nhiệm vụ học tập của bài mới (câu lệnh rẽ nhánh).",
"w7-067":"Hệ thống luyện tập cần đa dạng dạng bài. 12 bài cùng một dạng tính tổng là chưa đủ thể loại, nên thay bớt bằng các dạng khác (tìm kiếm, đếm, lọc…).",
"xd-001":"Yêu cầu cần đạt được xác định dựa trên ba căn cứ: pháp lí (văn bản của Đảng, Nhà nước, Bộ), lí luận và khoa học (nghiên cứu giáo dục, chuẩn quốc tế), và thực tiễn (điều kiện, kinh nghiệm dạy học trong nước). “Cơ sở xã hội” hay “cơ sở kinh tế” không phải nhóm căn cứ được nêu.",
"xd-002":"NLd (ứng dụng CNTT-TT trong học và tự học) góp phần trực tiếp vào năng lực tự chủ và tự học. Hai cặp còn lại: NLc (giải quyết vấn đề) tương ứng với năng lực giải quyết vấn đề và sáng tạo; NLe (hợp tác trong môi trường số) tương ứng với năng lực giao tiếp và hợp tác. Các phương án khác ghép sai cặp.",
"xd-003":"Ba mạch kiến thức cốt lõi là DL (Học vấn số hoá phổ thông), ICT (Công nghệ thông tin và truyền thông) và CS (Khoa học máy tính). AI, IoT hay “công nghệ phần mềm” chỉ là nội dung, chủ đề, không phải mạch kiến thức.",
"xd-004":"Bốn trụ cột của UNESCO là học để biết, học để làm, học để chung sống và học để khẳng định bản thân. Gắn 5 thành phần năng lực với các trụ cột này cho thấy môn học hướng tới phát triển toàn diện. Các phương án khác chỉ nhấn một mặt: lí thuyết, nghề nghiệp hoặc đạo đức mạng.",
"xd-005":"Ma trận đề đánh giá năng lực phải lấy yêu cầu cần đạt của chương trình môn học làm thước đo, và chỉ chọn mạch kiến thức đã học. Các phương án khác chuẩn hoá theo khung năng lực chung (không phải của môn), chọn bài theo tần suất xuất hiện trong học liệu, hoặc ưu tiên mạch theo cảm tính.",
"xd-006":"Học sinh chạy theo hình thức sản phẩm vì tiêu chí đánh giá chưa chỉ ra điều cốt lõi. Rubric đặt trọng số chủ yếu vào các yêu cầu cần đạt cốt lõi (như tư duy thuật toán) sẽ hướng sự chú ý của học sinh về đúng trọng tâm. Kiểm soát quy trình, phân hoá nhóm hay đánh giá chéo không xử lí trực tiếp nguyên nhân.",
"xd-007":"Cơ sở lí luận và khoa học để xác định nội dung là các báo cáo nghiên cứu và khung năng lực số quốc tế. Văn bản, chỉ thị của Đảng, Nhà nước là cơ sở pháp lí. Ý kiến chuyên gia, giáo viên và khảo sát hạ tầng, phòng máy là cơ sở thực tiễn.",
"xd-008":"Ở THPT, môn Tin học phân hoá thành hai định hướng (Tin học ứng dụng và Khoa học máy tính) với mục đích chính là định hướng nghề nghiệp cho học sinh. Các phương án khác là mục tiêu chung của môn hoặc của cấp học dưới.",
"xd-009":"Yêu cầu cần đạt có quan hệ nhiều–nhiều với nội dung: một yêu cầu (tự bảo vệ an toàn trên không gian mạng) được hình thành qua nhiều chủ đề. Vì vậy tích hợp mục tiêu này vào nhiều chủ đề để học sinh luyện tập trong nhiều bối cảnh là hiệu quả nhất. Dồn vào một bài, gộp vào dự án cuối năm hay chia nhỏ thành từng bài riêng đều không tạo được sự củng cố liên tục.",
"xd4-001":"Phương pháp dạy học và đánh giá được xác định dựa trên ba nhóm căn cứ: pháp lí (văn bản của Đảng, Nhà nước, Bộ), khoa học (lí luận dạy học, nghiên cứu giáo dục) và thực tiễn (điều kiện dạy học, kinh nghiệm thực tế). Các tổ hợp có “sư phạm”, “tâm lí”, “thực nghiệm” không phải cách phân nhóm căn cứ chính thức.",
"xd4-002":"Định hướng Tin học ứng dụng ở THPT thiên về sử dụng phần mềm, công cụ số để giải quyết công việc, nên dạy học thực hành (học sinh trực tiếp thao tác trên máy) giữ vai trò chủ đạo. Dạy học giải quyết vấn đề phù hợp hơn với định hướng Khoa học máy tính. Lưu ý: tài liệu gốc không ghi đáp án câu này.",
"xd4-003":"Vấn đề đạo đức, văn hoá trên môi trường số cần được hiểu qua các tình huống cụ thể. Phân tích các trường hợp ứng xử thực tế rồi thảo luận cách phản hồi đúng mực giúp học sinh tự rút ra chuẩn mực. Thuyết giảng để ghi nhớ quy tắc, hay làm sản phẩm theo luật cố định, không tạo được sự thấu hiểu đó.",
"xd4-004":"Khái niệm Tin học thường trừu tượng (thuật toán, dữ liệu, mạng…). Dùng mô hình trực quan kèm ví dụ thực tế gắn với nhiệm vụ cụ thể giúp học sinh “nhìn thấy” khái niệm và hiểu sâu. Giảng giải có cấu trúc, lặp lại để ghi nhớ hay chỉ thảo luận nhóm thì kém hiệu quả hơn với nội dung trừu tượng.",
"xd4-005":"Mỗi mạch đánh giá một trọng tâm khác nhau: CS (Khoa học máy tính) đánh giá tư duy sáng tạo và có hệ thống; DL (Học vấn số hoá phổ thông) đánh giá thái độ, hành vi trên môi trường số; ICT (Công nghệ thông tin và truyền thông) đánh giá khả năng ứng dụng để tạo ra sản phẩm. Các bộ ba còn lại ghép trọng tâm chưa đúng hoặc thiên về ghi nhớ.",
"xd4-006":"Chủ đề D (Đạo đức, pháp luật và văn hoá trong môi trường số) cần hình thành thói quen ứng xử đúng. Học qua tình huống và dự án nhỏ cho học sinh phân tích các tình huống thực tế, từ đó rèn thói quen số phù hợp. Học thuộc quy tắc an ninh mạng, giảm thời gian thao tác, hay chỉ mô phỏng trực tuyến đều không phải lí do cốt lõi.",
"xd4-007":"Ở tiểu học, định hướng dạy học phân hoá là tổ chức các hoạt động đa dạng để khuyến khích, nuôi dưỡng những năng lực và sở thích khác nhau khi sử dụng máy tính. Cho học sinh chọn chủ đề tự chọn để khơi gợi đam mê, khám phá tiềm năng khoa học máy tính là định hướng ở THCS; dùng phương pháp riêng cho từng định hướng là ở THPT.",
"xd4-008":"Công cụ số lưu lịch sử chỉnh sửa (Google Docs, Git…) ghi lại khách quan và liên tục ai đã đóng góp gì trong suốt dự án. Đánh giá đồng đẳng ở cuối dự án hay báo cáo của nhóm trưởng mang tính chủ quan; quan sát trên lớp chỉ thấy được phần làm việc tại lớp.",
"xd4-009":"Chủ đề Mạng máy tính và Internet gắn với thiết bị và phần mềm thực tế, nên nên dạy ở phòng máy bằng phương pháp thực hành để học sinh thao tác phần mềm, quan sát thiết bị phần cứng. Học thuần lí thuyết, tập trung vào chuẩn mực đạo đức hay hướng nghiệp đều lệch trọng tâm chủ đề.",
"xd4-010":"Tin học 9 thuộc THCS. Ở cấp này, định hướng phân hoá là đưa ra các chủ đề tự chọn để mỗi học sinh chọn theo sở thích, phát triển hứng thú và khám phá tiềm năng về khoa học máy tính. Tổ chức hoạt động đa dạng cho mọi em thử nhiều loại nhiệm vụ là định hướng của tiểu học; hai phương án còn lại nói về phương pháp dạy học chứ không phải phân hoá.",
"xd5-001":"Kế hoạch giáo dục của nhà trường trước hết phải bảo đảm tính pháp lí: tuân thủ chương trình giáo dục phổ thông và các văn bản hướng dẫn của Bộ, Sở. Đây là yêu cầu bắt buộc được tài liệu chọn làm đáp án; các phương án khác chỉ là đặc điểm mong muốn của một kế hoạch tốt.",
"xd5-002":"Theo tài liệu tập huấn, quy trình xây dựng kế hoạch giáo dục nhà trường theo định hướng phát triển phẩm chất, năng lực ở THPT gồm 3 bước. Đây là câu hỏi ghi nhớ số liệu, nên cần nhớ con số này.",
"xd5-003":"Kế hoạch giáo dục nhà trường phải linh hoạt, phù hợp với điều kiện cụ thể của địa phương và nhà trường, trên nền chương trình chung. Làm đồng loạt như nhau trên cả nước, hay tách rời thực tế địa phương, đều trái yêu cầu này; điều chỉnh mục tiêu bài học theo trình độ học sinh là việc của từng giáo viên.",
"xd5-004":"Kế hoạch giáo dục nhà trường là văn bản định hướng để tổ chuyên môn và từng giáo viên xây dựng kế hoạch dạy học, kế hoạch giáo dục cá nhân. Mọi kế hoạch cấp dưới đều căn cứ vào nó, nên đây là cấp quan trọng nhất khi triển khai chương trình. Các phương án khác chỉ là tác dụng phụ.",
"xd5-005":"Với môn có ít tiết (khi thiếu phòng học bộ môn hoặc giáo viên), nhà trường không bắt buộc rải đều các tiết qua mọi tuần: có thể dồn môn đó vào một số tuần hoặc học kì để linh hoạt. Yêu cầu số tiết mỗi tuần bằng nhau hay phải trải đều cả năm là làm mất tính linh hoạt.",
"xd5-006":"Tham quan, cắm trại, câu lạc bộ, hoạt động cộng đồng là các hoạt động trải nghiệm. Mục tiêu của chúng là tạo môi trường để học sinh vận dụng kiến thức, kĩ năng đã học vào tình huống thực tế, chứ không nhằm ghi nhớ lí thuyết, nâng điểm số hay ghi chép tốt hơn.",
"xd5-007":"Không. Chương trình giáo dục phổ thông 2018 là nền tảng cốt lõi; chương trình (kế hoạch) nhà trường được xây dựng, tham chiếu và điều chỉnh dựa trên nó. Nói kế hoạch nhà trường “quan trọng nhất” là xét ở khâu triển khai, không phải đặt nó cao hơn chương trình quốc gia. Phạm vi áp dụng rộng hay hẹp không phải lí do cốt lõi.",
"xd5-008":"42 học sinh với 25 máy thì chia nhóm 2–3 em dùng chung một máy, để cả lớp cùng thực hành trong giờ và hỗ trợ lẫn nhau. Thay phiên nhau thì nhiều em phải chờ; chia đôi lớp hay giao về nhà thực hành thì khó tổ chức, không bảo đảm mọi em có máy và mất sự hướng dẫn của giáo viên.",
"xd5-009":"Cha mẹ học sinh được tham gia góp ý xây dựng và giám sát thực hiện kế hoạch giáo dục, nhưng không có thẩm quyền can thiệp vào chuyên môn, sư phạm hay tự ý sửa bài dạy. Chuyên môn thuộc trách nhiệm của giáo viên, tổ chuyên môn và hiệu trưởng.",
"xd6-001":"Bốn yêu cầu khi xây dựng kế hoạch giáo dục của tổ chuyên môn là: bảo đảm tính pháp lí, tính khả thi, tính logic và tính linh hoạt. “Tính giải trí” không nằm trong các yêu cầu này.",
"xd6-002":"Kế hoạch giáo dục của tổ chuyên môn phải bảo đảm bốn tính: pháp lí, khả thi, logic và linh hoạt. Các tổ hợp khác thay vào “khoa học”, “thực tiễn”, “sáng tạo” hay “hiệu quả”, không đúng bộ yêu cầu.",
"xd6-003":"Tính linh hoạt cho phép điều chỉnh kế hoạch khi tình hình thực tế thay đổi (lịch học, điều kiện, đối tượng học sinh…). Pháp lí là tuân thủ quy định; khả thi là phù hợp điều kiện thực hiện; logic là sự nhất quán giữa các phần của kế hoạch.",
"xd6-004":"Việc điều chỉnh này là hợp lí: xây dựng kế hoạch gồm nhiều nhiệm vụ liên quan nhau (phân phối chương trình, hoạt động giáo dục, kiểm tra…), nên thay đổi một phần có thể kéo theo điều chỉnh phần khác. Kế hoạch không bất biến, cũng không cần Sở phê duyệt cho điều chỉnh cấp tổ.",
"xd6-005":"Hiệu trưởng là người phê duyệt kế hoạch giáo dục của tổ chuyên môn cho cả năm học; đó là căn cứ để giáo viên thực hiện. Tổ trưởng chuyên môn chủ trì xây dựng, phó hiệu trưởng có thể giúp quản lí, còn bí thư chi bộ không có thẩm quyền phê duyệt chuyên môn.",
"xd6-006":"Kế hoạch giáo dục của tổ chuyên môn nhằm bảo đảm thực hiện thống nhất kế hoạch nhà trường, đồng thời là căn cứ để kiểm tra, đôn đốc và đánh giá hiệu quả công việc. Các phương án khác thu hẹp mục đích (chỉ phân công nhiệm vụ, chỉ đánh giá năng lực cá nhân, chỉ làm giáo án).",
"xd6-007":"Phân tích năng lực học sinh, số lượng, chất lượng giáo viên và cơ sở vật chất, có tính đến sự khác biệt giữa chúng, là để kế hoạch phù hợp điều kiện thực tế và thực hiện được. Đó là tính khả thi.",
"xd6-008":"Kế hoạch dựa vào phòng máy trong khi phòng máy đang bảo trì, không dùng được, tức là kế hoạch không thực hiện được trong điều kiện hiện có. Như vậy yêu cầu bị vi phạm là tính khả thi.",
"xd6-009":"Khi thiết bị không đủ cho số tiết dự kiến, tổ chuyên môn cần linh hoạt: xếp thực hành theo ca, tận dụng công cụ, học liệu bên ngoài, hoặc điều chỉnh phân phối chương trình. Bắt học sinh tự trang bị, bỏ hết bài thực hành hay chuyển toàn bộ sang lí thuyết đều làm sai mục tiêu chương trình.",
"xd7-001":"Kế hoạch bài dạy theo Công văn 5512 gồm chuỗi bốn hoạt động: mở đầu (đặt vấn đề), hình thành kiến thức mới, luyện tập và vận dụng. “Giao nhiệm vụ – thực hiện – báo cáo, thảo luận – kết luận” là bốn bước tổ chức trong từng hoạt động, không phải chuỗi hoạt động của bài.",
"xd7-002":"Thứ tự hợp lí: (2) xác định mục tiêu bài học, rồi (1) xác định chuỗi hoạt động học và mục tiêu từng hoạt động, (4) thiết kế cụ thể từng hoạt động dạy học, cuối cùng (3) hoàn thiện kế hoạch bài dạy. Tức là 2-1-4-3. Mục tiêu phải có trước mới thiết kế được hoạt động, và hoàn thiện luôn là bước cuối.",
"xd7-003":"Kế hoạch bài dạy tốt tạo ra môi trường để dạy và học hiệu quả, đồng thời giúp giáo viên rèn kĩ năng dạy học qua mỗi lần thiết kế và điều chỉnh. Các phương án khác nhấn vào phòng ngừa sự cố, truyền thụ lí thuyết hay đánh giá sau giờ giảng, không phản ánh vai trò cốt lõi.",
"xd7-004":"Ôn lại bài cũ khi dự đoán học sinh chưa vững kiến thức nền là khai thác hiệu quả vốn kiến thức đã có, làm điểm tựa cho kiến thức mới. Đây là một yêu cầu khi thiết kế kế hoạch bài dạy.",
"xd7-005":"Vai trò tổ chức, hướng dẫn của giáo viên và tính tích cực của học sinh thể hiện ở việc kế hoạch tập trung thiết kế nhiệm vụ học tập cho học sinh thực hiện, thay vì mô tả hoạt động giảng giải của giáo viên. Các phương án khác là yêu cầu về phương pháp, tính logic của chuỗi hoạt động và tính linh hoạt.",
"xd7-006":"Giáo viên vào bài bằng giải thích cú pháp ngay, bỏ qua khâu mở đầu (đặt vấn đề, tạo nhu cầu dùng vòng lặp) và không có hoạt động vận dụng. Vì vậy chuỗi hoạt động chưa đủ tiến trình mở đầu → hình thành kiến thức → luyện tập → vận dụng. Việc hỏi đáp để tránh giảng một chiều cho thấy giáo viên đã chú ý đến tính tích cực của học sinh.",
"xd7-007":"Phần Mục tiêu của kế hoạch bài dạy gồm ba ý: yêu cầu cần đạt, năng lực, và phẩm chất. “Kiến thức, kĩ năng, thái độ” là cách viết mục tiêu theo chương trình cũ.",
"xd7-008":"Các câu hỏi giáo viên đặt ra sau khi học sinh trình bày, để kiểm tra mức độ hiểu, thuộc bước báo cáo, thảo luận của hoạt động học. Kết luận, nhận định là bước sau đó, khi giáo viên chốt kiến thức.",
"xd7-009":"Trong mỗi hoạt động học, mục “Nội dung” mô tả nhiệm vụ giáo viên giao cho học sinh (câu hỏi, bài tập, tình huống). Kết quả học sinh làm ra thuộc mục “Sản phẩm”; kiến thức giáo viên chốt nằm ở bước kết luận trong “Tổ chức thực hiện”.",
"xd7-010":"Kế hoạch bài dạy là bản định hướng, có thể điều chỉnh theo diễn biến thực tế của giờ học và nhu cầu của học sinh. Kéo dài phần lập trình khi cả lớp gặp khó là hợp lí. Kế hoạch không đòi hỏi thời gian thực tế khớp tuyệt đối, cũng không cần tổ duyệt lại giữa giờ.",
"xd7-011":"Phần tổ chức thực hiện hoạt động nên dự kiến khó khăn học sinh có thể gặp (như quên lệnh dừng vòng lặp), câu hỏi hoặc gợi ý hỗ trợ, và các mức độ hoàn thành nhiệm vụ. Như vậy giáo viên hỗ trợ kịp thời mà không làm thay. Phát chương trình mẫu là làm thay; danh sách gọi trình bày hay tiêu chí chấm không xử lí được khó khăn đã dự đoán.",
"and1-001":"Thuộc tính android:textColor quy định màu chữ của TextView. textSize là cỡ chữ, textStyle là kiểu chữ (đậm, nghiêng), còn textAlignment là căn lề văn bản.",
"and1-002":"Android được xây dựng trên nhân Linux (Linux Kernel). Đây là tầng thấp nhất, quản lý phần cứng, bộ nhớ và tiến trình. MacOS, Windows và Unix không phải nền tảng của Android.",
"and1-003":"File giao diện activity_main.xml nằm trong res/layout, thư mục chứa các layout XML. res/drawable chứa hình ảnh, res/values chứa chuỗi, màu, kích thước; src/main/java chứa mã nguồn.",
"and1-004":"Lớp R (R.java) được Android Studio sinh tự động, chứa ID của mọi tài nguyên (layout, string, drawable, id…) để code tham chiếu, ví dụ R.layout.activity_main hay R.id.btnOk.",
"and1-005":"Thiết bị di động là thiết bị nhỏ gọn, mang theo được: điện thoại thông minh, máy tính bảng, đồng hồ thông minh. Máy tính để bàn đặt cố định nên không được xem là thiết bị di động.",
"and1-006":"Khi bấm Run, ứng dụng được cài và chạy trên máy ảo (Emulator) hoặc điện thoại thật nối với máy tính. Logcat chỉ hiện nhật ký (log), Terminal là cửa sổ dòng lệnh, build.gradle là file cấu hình.",
"and1-007":"findViewById(R.id.ten_id) tìm View có ID tương ứng trong layout đã nạp và trả về đối tượng để dùng trong Java. Các tên getViewById, mapViewById, setViewById không tồn tại.",
"and1-008":"Giao diện chính thường được thiết kế trong res/layout/activity_main.xml. MainActivity.java chứa phần xử lý, AndroidManifest.xml khai báo cấu hình ứng dụng, strings.xml chứa chuỗi.",
"and1-009":"build.gradle là file cấu hình build: khai báo thư viện phụ thuộc (dependencies), phiên bản SDK, cấu hình biên dịch và đóng gói ứng dụng. Nó không quản lý giao diện, chuỗi hay class Java.",
"and1-010":"Để tạo project mới, chọn New Project (Create New Project). Open mở project có sẵn, Import Module thêm module vào project đang mở, New → File chỉ tạo một file.",
"and1-011":"styles.xml (themes.xml ở các bản mới) định nghĩa theme và style: màu chủ đạo, phông chữ, định dạng chung cho các View. Chuỗi nằm ở strings.xml, layout ở res/layout.",
"and1-012":"Mã nguồn Java/Kotlin đặt trong src/main/java, chia theo package. Thư mục res/ chứa tài nguyên (layout, values, drawable…), assets/ chứa file thô đi kèm ứng dụng.",
"and1-013":"Linux Kernel là tầng thấp nhất trong kiến trúc Android, quản lý CPU, bộ nhớ, tiến trình và driver phần cứng. Các tầng trên (Native Libraries, Android Runtime, Application Framework) dựa vào nó.",
"and1-014":"build.gradle (Project) là file Gradle mức project, áp dụng cho mọi module. build.gradle (Module: app) cấu hình riêng module app; settings.gradle khai báo các module trong project.",
"and1-015":"colors.xml (trong res/values) khai báo các mã màu đặt tên, ví dụ <color name=\"pink\">#FF4081</color>, để dùng lại trong toàn ứng dụng.",
"and1-016":"Khi tạo AVD ta chọn kiểu thiết bị (kích thước, độ phân giải màn hình ảo) và System Image (phiên bản Android). RAM của máy tính thật là phần cứng sẵn có, không phải thứ cấu hình trong AVD.",
"and1-017":"Native App trên Android được viết bằng ngôn ngữ chính thức của nền tảng là Java và Kotlin. HTML/CSS dùng cho web hoặc ứng dụng hybrid; C#/.NET dùng với Xamarin/MAUI.",
"and1-018":"Theo đáp án của bài, icon của ứng dụng được quản lý trong res/drawable, nơi chứa hình ảnh và đồ hoạ. Lưu ý: trong project hiện nay, icon khởi chạy (ic_launcher) thường đặt ở res/mipmap, như câu hỏi về thay đổi app icon.",
"and1-019":"padding là khoảng cách bên trong View, giữa viền và nội dung. margin là khoảng cách bên ngoài, giữa View với các View xung quanh. gravity căn nội dung, textAlignment căn văn bản.",
"and1-020":"textAlignment căn lề văn bản (trái, giữa, phải) trong TextView. layout_margin là khoảng cách bên ngoài; textStyle, textSize là kiểu chữ và cỡ chữ.",
"and1-021":"dimens.xml (res/values) lưu các giá trị kích thước như 16dp, 14sp để dùng lại. strings.xml lưu chuỗi, colors.xml lưu màu, styles.xml lưu theme và style.",
"and1-022":"Muốn chạy thử ứng dụng trên máy tính cần tạo máy ảo Android (Emulator/AVD) qua Device Manager. Service, Broadcast Receiver là thành phần của ứng dụng, không phải môi trường chạy.",
"and1-023":"AndroidManifest.xml khai báo thông tin cốt lõi: tên package, icon, tên ứng dụng, các Activity và quyền truy cập (permission). Hệ thống đọc file này trước khi chạy ứng dụng.",
"and1-024":"Các giá trị dùng chung được tách vào res/values: strings.xml (chuỗi), colors.xml (màu), styles.xml (định dạng, theme). Cách này giúp dễ sửa đổi và dịch ngôn ngữ.",
"and1-025":"Flutter (Google, ngôn ngữ Dart) là framework Cross Platform: một mã nguồn chạy được trên cả Android và iOS. Objective-C, Swift (iOS) và Java (Android) dùng cho ứng dụng native.",
"and1-026":"Icon khởi chạy của ứng dụng (ic_launcher) nằm trong res/mipmap, có nhiều bản cho từng mật độ màn hình. Tên file icon được khai báo trong AndroidManifest.xml (android:icon).",
"and1-027":"Hình ảnh, icon dùng trong giao diện thường đặt ở res/drawable. Riêng icon khởi chạy ứng dụng đặt ở res/mipmap; res/layout chứa giao diện, res/values chứa chuỗi và màu.",
"and1-028":"Hybrid App được viết bằng công nghệ web (HTML, CSS, JavaScript) rồi chạy trong một WebView đóng gói thành ứng dụng, ví dụ Cordova/Ionic. Java/Kotlin, Swift dùng cho native.",
"and1-029":"Gắn sự kiện bấm cho Button bằng button.setOnClickListener(new View.OnClickListener() { … }) hoặc lambda. OnClickListener là tên interface; addClickEvent, setOnClick không tồn tại.",
"and1-030":"ViewGroup là View đặc biệt có thể chứa View con, ví dụ LinearLayout, RelativeLayout, ConstraintLayout. Button, EditText là View đơn lẻ; Toast là thông báo nổi, không phải container.",
"and1-031":"editText.getText() trả về nội dung người dùng nhập (kiểu Editable), thường gọi thêm .toString() để lấy chuỗi. setText() là đặt nội dung; show() không thuộc EditText.",
"and1-032":"TextView dùng để hiển thị văn bản lên màn hình. Nhập văn bản là việc của EditText, hiển thị hình ảnh là ImageView, thông điệp ngắn tự tắt là Toast.",
"and1-033":"CheckBox cho phép chọn nhiều lựa chọn cùng lúc, mỗi ô bật/tắt độc lập. Chỉ chọn một là đặc điểm của RadioButton trong RadioGroup. CheckBox có thể kèm văn bản và đặt trong bất kỳ layout nào.",
"and2-001":"Toast có hai độ dài chuẩn: LENGTH_SHORT khoảng 2 giây và LENGTH_LONG khoảng 3,5 giây.",
"and2-002":"android:layout_below=\"@id/x\" đặt View nằm ngay dưới View có id x. layout_above đặt phía trên, layout_toLeftOf đặt bên trái, layout_alignBottom căn thẳng cạnh dưới.",
"and2-003":"android:layout_toRightOf=\"@id/x\" đặt View nằm bên phải View có id x. layout_alignRight căn thẳng cạnh phải, layout_alignParentRight dính vào cạnh phải View cha.",
"and2-004":"Gõ new + dấu cách rồi nhấn Ctrl + Space để bật gợi ý code (code completion), chọn View.OnClickListener để Android Studio tự sinh khung hàm onClick. Alt + Enter dùng để sửa lỗi, import nhanh.",
"and2-005":"CheckBox cho chọn nhiều lựa chọn cùng lúc. RadioButton (trong RadioGroup) chỉ cho chọn một; Button để bấm thực hiện lệnh; TextView để hiển thị chữ.",
"and2-006":"android:orientation (horizontal hoặc vertical) quy định LinearLayout xếp các View con theo hàng ngang hay cột dọc. layout_gravity căn vị trí của View; direction và layout_align không phải thuộc tính của LinearLayout.",
"and2-007":"android:hint hiển thị chữ gợi ý mờ trong EditText khi chưa nhập gì (giống placeholder trên web). Android không có thuộc tính placeholder; text là nội dung thật.",
"and2-008":"Trong ConstraintLayout, tên thuộc tính đọc là “cạnh của View này _to_ cạnh của View kia”. layout_constraintTop_toBottomOf nối cạnh trên View này với cạnh dưới View kia; Bottom_toTopOf thì ngược lại.",
"and2-009":"android:layout_centerInParent=\"true\" đặt View vào chính giữa View cha theo cả hai chiều. centerHorizontal chỉ giữa theo chiều ngang, centerVertical chỉ giữa theo chiều dọc.",
"and2-010":"Mỗi View trong ConstraintLayout cần ít nhất 2 ràng buộc: một theo chiều ngang và một theo chiều dọc. Thiếu thì View bị kéo về góc trên bên trái khi chạy.",
"and2-011":"ViewGroup chứa được nhiều View và cả ViewGroup khác, nên các layout có thể lồng nhau. ViewGroup không chỉ chứa TextView và dùng được ở mọi loại layout.",
"and2-012":"Button không tự hiện Toast khi được nhấn; muốn hiện Toast phải viết code trong sự kiện onClick. Các ý còn lại đều đúng: Button hiển thị nút bấm, gắn được onClickListener và hay đi cùng EditText.",
"and2-013":"View là thành phần cơ bản của giao diện: hiển thị nội dung (chữ, hình) hoặc nhận tương tác (bấm, nhập). Container chứa View khác là ViewGroup; View dùng được trong mọi layout.",
"and2-014":"Toast hiện một thông điệp ngắn rồi tự tắt sau khoảng 2 hoặc 3,5 giây, người dùng không cần bấm. Thời gian không phải 10 giây và Toast không phụ thuộc layout.",
"and2-015":"Trong ConstraintLayout, mỗi View cần tối thiểu một ràng buộc ngang và một ràng buộc dọc để xác định vị trí. Đây là layout mặc định, được khuyến khích dùng, và không giới hạn số View con.",
"and2-016":"gravity=\"center_horizontal\" căn nội dung bên trong View ra giữa theo chiều ngang. Giữa theo chiều dọc là center_vertical; giữa cả hai chiều là center.",
"and2-017":"Toast tự biến mất sau 2 giây (SHORT) hoặc 3,5 giây (LONG), người dùng không phải bấm để đóng. Nội dung thông điệp tuỳ chỉnh được.",
"and2-018":"Nói CheckBox chỉ cho chọn duy nhất một đáp án là sai: chọn một là đặc điểm của RadioButton trong RadioGroup. CheckBox là một loại View, cho chọn nhiều đáp án, hay dùng cho câu hỏi nhiều lựa chọn.",
"and2-019":"ListView hiển thị một danh sách cuộn, mỗi phần tử một dòng. ListView dùng trong Activity, hiển thị được mọi kiểu dữ liệu, nhưng cần Adapter để đổ dữ liệu vào.",
"and2-020":"AlertDialog là hộp thoại nổi để thông báo và tương tác với người dùng (tiêu đề, nội dung, các nút như OK, Huỷ). Nó không thay thế Activity và thường có nút.",
"and2-021":"Nút “Huỷ” (NegativeButton) thường dùng để đóng hộp thoại mà không làm gì thêm, nên cửa sổ AlertDialog đóng lại. Mở Activity, hiện Toast hay thoát ứng dụng chỉ xảy ra nếu lập trình thêm.",
"and2-022":"EditText là ô nhập liệu, nhận được chữ, số, ngày tháng… tuỳ thuộc tính inputType. EditText hỗ trợ hint và dùng được trong mọi layout.",
"and2-023":"Khi đặt các RadioButton trong cùng một RadioGroup, người dùng chỉ chọn được một lựa chọn; chọn cái mới thì cái cũ tự bỏ chọn. Chọn nhiều cùng lúc là CheckBox.",
"and2-024":"Sai ở chỗ cho rằng không dùng được Button trong AlertDialog tuỳ chỉnh. Dialog tuỳ chỉnh dùng một file layout .xml riêng, trong đó đặt được Button, EditText… rồi ánh xạ (findViewById) để xử lý.",
"and2-025":"Phải gọi show() thì AlertDialog mới hiện. Quy trình: tạo AlertDialog.Builder, đặt tiêu đề, nội dung, nút, rồi create() và show(), thường đặt trong sự kiện như bấm nút.",
"and2-026":"Hành động “gửi câu trả lời” là một lệnh người dùng bấm để thực hiện, nên dùng Button. CheckBox, RadioButton dùng để chọn đáp án; TextView chỉ hiển thị chữ.",
"and3-001":"LinearLayout xếp các View con thành một hàng ngang hoặc một cột dọc, theo thuộc tính orientation. Xếp theo quan hệ với View cha hay View khác là RelativeLayout; theo toạ độ tuyệt đối là AbsoluteLayout (đã bỏ).",
"and3-002":"ListView cần Adapter làm cầu nối: Adapter lấy dữ liệu (mảng, danh sách) và tạo View cho từng dòng. ViewModel, Listener, Handler không đảm nhận việc này.",
"and3-003":"builder.create() tạo đối tượng AlertDialog từ Builder, sau đó gọi show() để hiện. Các hàm make(), init(), build() không thuộc AlertDialog.Builder.",
"and3-004":"View là đơn vị cơ bản nhất của giao diện Android: mọi thành phần như TextView, Button đều là View. ViewGroup là View chứa View khác; Activity là màn hình; Service chạy nền, không có giao diện.",
"and3-005":"setTitle() đặt tiêu đề cho AlertDialog. setMessage() đặt nội dung, setIcon() đặt biểu tượng, setPositiveButton() thêm nút đồng ý.",
"and3-006":"TextView dùng để hiển thị văn bản. Button là nút bấm, ImageView hiển thị hình ảnh, CheckBox là ô chọn.",
"and3-007":"AlertDialog nhiều lớp là mở thêm hộp thoại khác khi người dùng bấm nút: trong sự kiện của PositiveButton hoặc NegativeButton, tạo thêm một AlertDialog.Builder con rồi show(). Không cần RecyclerView.",
"and3-008":"Nói ViewGroup không thể lồng nhau là sai. ViewGroup là một loại View, chứa được cả ViewGroup khác (layout lồng layout), và gồm LinearLayout, RelativeLayout, ConstraintLayout…",
"and3-009":"Nói không thể tạo nhiều lớp AlertDialog là sai. Có thể lồng AlertDialog con trong các nút của hộp thoại cha. Quy trình mỗi lớp giống AlertDialog một lớp, và nên tách hàm riêng cho từng hộp thoại.",
"and3-010":"Theo đáp án của bài, phát biểu sai là ArrayAdapter “không thể tuỳ chỉnh giao diện từng dòng”: có thể truyền layout riêng cho dòng hoặc kế thừa ArrayAdapter để tuỳ biến. ArrayAdapter nối mảng/danh sách với ListView và được khởi tạo bằng context, layout, dữ liệu.",
"and3-011":"Nói ListView không dùng được trong Activity là sai: ListView thường được đặt ngay trong layout của Activity. ListView cần Adapter (ví dụ ArrayAdapter) và hiển thị dữ liệu theo từng dòng.",
"and3-012":"Nói View chỉ có thể chứa View khác là sai: đó là đặc điểm của ViewGroup. View hiển thị nội dung hoặc nhận tương tác (TextView, Button, ImageView) và là thành phần cơ bản nhất của giao diện.",
"and3-013":"AlertDialog tuỳ chỉnh cần một file layout .xml riêng cho phần giao diện của Dialog, rồi gắn vào bằng setView(). Dialog tuỳ chỉnh vẫn có Button và dùng được ngay trong Activity.",
"and3-014":"Các bước tạo AlertDialog một lớp: khởi tạo AlertDialog.Builder; đặt tiêu đề, nội dung, nút (setTitle, setMessage, setPositiveButton…); gọi create() rồi show(). Không cần Activity mới.",
"and3-015":"Chọn nhiều dịch vụ khám cùng lúc là chọn nhiều, nên dùng CheckBox. RadioButton chỉ chọn một, EditText để nhập chữ, Spinner là danh sách thả xuống chọn một mục.",
"and3-016":"ListView cơ bản chỉ hiển thị dữ liệu. Muốn thành ứng dụng To-do-list phải tự lập trình thêm chức năng Thêm/Sửa/Xoá công việc và cập nhật Adapter. ListView không tự sửa dữ liệu.",
"and3-017":"Trong ví dụ AlertDialog một lớp của bài, nút OK được lập trình để hiển thị một thông điệp Toast. Kết quả phụ thuộc code trong setPositiveButton, không tự đóng ứng dụng hay mở Activity mới.",
"and3-018":"Thông báo ngắn gọn, tự tắt (như hiện đáp án đúng) phù hợp nhất với Toast. AlertDialog dùng khi cần người dùng xác nhận; EditText để nhập, ImageView để hiện hình.",
"and3-019":"“Đăng nhập” là hành động người dùng bấm để thực hiện, nên dùng Button và xử lý trong onClick. Toast chỉ để thông báo; CheckBox, RadioButton dùng để chọn.",
"and3-020":"Nói không cần cập nhật Adapter là sai: sau khi thêm, sửa hay xoá dữ liệu phải gọi adapter.notifyDataSetChanged() thì ListView mới hiển thị thay đổi. Các ý còn lại là phần cần có của To-do-list.",
"and4-001":"Trong Java, this tham chiếu tới đối tượng hiện tại của lớp, ví dụ this.danhSach = danhSach. super tham chiếu lớp cha, return trả giá trị; self là từ khoá của Python, không phải Java.",
"and4-002":"show() hiển thị AlertDialog lên màn hình; có thể gọi trên Builder hoặc trên đối tượng tạo bằng create(). open(), start(), display() không phải phương thức của AlertDialog.",
"and4-003":"Ô tìm kiếm SearchView bắt từ khoá qua listener OnQueryTextListener (gắn bằng setOnQueryTextListener), với hai hàm onQueryTextSubmit và onQueryTextChange. Theo đáp án của bài, chọn onQueryTextListener().",
"and4-004":"Phương thức không trả về giá trị khai báo kiểu void, ví dụ public void hienThi(). null là giá trị rỗng của tham chiếu; NaN là “không phải số” của số thực; empty không phải từ khoá Java.",
"and4-005":"Override onCreateOptionsMenu(Menu menu) rồi gọi getMenuInflater().inflate(R.menu.ten_menu, menu) để gắn menu XML vào Activity. onOptionsItemSelected() xử lý khi chọn một mục trong menu.",
"and4-006":"Custom Adapter cho ListView thường kế thừa ArrayAdapter<T> (hoặc BaseAdapter) rồi override getView() để tự tạo giao diện từng dòng. RecyclerView.Adapter dùng cho RecyclerView, không phải ListView.",
"and4-007":"Theo trình tự trong bài, bước đầu tiên là khai báo ListView trong file layout .xml. Sau đó chuẩn bị dữ liệu, tạo ArrayAdapter và gọi setAdapter() để gắn vào ListView.",
"and4-008":"ListView hiển thị dữ liệu theo dạng danh sách từng dòng. GridView hiển thị dạng lưới, Spinner là danh sách thả xuống; RecyclerView cũng hiển thị danh sách nhưng là thành phần nâng cao hơn, đáp án của bài là ListView.",
"and4-009":"setIcon(R.drawable.ten_icon) đặt biểu tượng cho AlertDialog. setDrawable, setImage, setPicture không phải phương thức của AlertDialog.Builder.",
"and4-010":"Custom Adapter nối dữ liệu với layout của từng dòng và quyết định mỗi item hiển thị thế nào (ảnh, nhiều TextView…). Nó không thay ListView, không lưu dữ liệu và không tự sắp xếp.",
"and4-011":"getView() được gọi cho từng dòng: inflate layout của item (hoặc dùng lại convertView), ánh xạ các View con rồi gán dữ liệu của phần tử tại vị trí position vào. Nó không khởi tạo Activity hay tạo menu.",
"and4-012":"Nói ListView tự hiển thị dữ liệu mà không cần Adapter là sai. Các bước đúng: tạo ListView trong .xml, chuẩn bị mảng hoặc danh sách dữ liệu, rồi liên kết bằng ArrayAdapter.",
"and4-013":"ArrayAdapter là cầu nối giữa dữ liệu (mảng, ArrayList) và ListView. Nó làm việc với mọi kiểu dữ liệu, dùng cho ListView (không chỉ RecyclerView) và có thể tuỳ biến giao diện.",
"and4-014":"Nói AlertDialog thay thế hoàn toàn Activity là sai. AlertDialog chỉ là hộp thoại nổi trên Activity: hiển thị được tiêu đề, nội dung, icon, các nút OK/Cancel và cả giao diện tuỳ chỉnh từ XML.",
"and4-015":"convertView là View của một dòng cũ đã cuộn khỏi màn hình. Nếu nó null thì mới inflate layout mới; nếu không thì dùng lại. Nhờ vậy ListView không phải tạo View mới cho mỗi dòng, chạy mượt và tiết kiệm bộ nhớ.",
"and4-016":"Trong ứng dụng quản lý công việc, sự kiện nhấn giữ (setOnItemLongClickListener) thường mở AlertDialog cho người dùng chọn Sửa hoặc Xoá công việc. ListView không tự xoá dòng hay đổi chế độ.",
"and4-017":"extends nghĩa là kế thừa: MayTinhAdapter kế thừa thuộc tính và phương thức của lớp cha ArrayAdapter<MayTinh>, rồi gọi super(...) để khởi tạo phần lớp cha. Triển khai interface dùng implements; tạo đối tượng dùng new.",
"and4-018":"Nói ListView tự sửa dữ liệu là sai: phải tự lập trình, ví dụ nhấn giữ để mở AlertDialog, cho người dùng sửa nội dung, cập nhật danh sách, rồi gọi notifyDataSetChanged() để Adapter làm mới.",
"and4-019":"Chức năng Thêm công việc cần EditText để nhập nội dung và Button để xác nhận. Khi bấm, thêm phần tử vào danh sách rồi cập nhật Adapter. Khai báo ListView không tự thêm được, và setMessage chỉ đặt chữ cho hộp thoại.",
"and4-020":"Hàm khởi tạo ArrayAdapter cần context (Activity hiện tại), layout cho mỗi dòng (ví dụ android.R.layout.simple_list_item_1) và danh sách dữ liệu: new ArrayAdapter<>(this, layout, data).",
"and4-021":"Nói công việc tự xoá khi nhấn vào bất kỳ TextView nào là sai: xoá phải do người dùng chủ động chọn, thường nhấn giữ một dòng, xác nhận bằng AlertDialog, rồi xoá khỏi danh sách và cập nhật Adapter."};
